// Real dive sites and real species. Depths in metres, sizes in metres (typical adult length; wingspan for rays).
// regions: where it lives — MV Maldives, EG Egypt (Red Sea), ID Indonesia, AU Australia, PW Palau, 'all' (widespread incl. the Maldives)
// or 'world' (not found in the Maldives; see range). Site current: [speed m/s, compass bearing it flows toward]. pred = hunts other fish; mood = curious | puff | hide. bait = forms bait balls. tints = colour morphs for individuals.
// depth = recorded range, typ = where it's usually found, ab = how common (expected groups per 10 m of water).
// iucn: LC NT VU EN CR DD (data deficient) NE (not evaluated).
const REEF_DATA = {
  maldives: { name: 'Maldives', blurb: '26 coral atolls in the central Indian Ocean, famous for manta rays, whale sharks and reef sharks along channel walls.', surf: 29, deep: 2 },

  sites: [
    // Maldives
    { id: 'banana_reef', country: 'MV', target: { id: 'napoleon', hint: 'A huge wrasse with a bulging forehead patrols the outer reef edge, 10–30 m.' }, current: [0.35, 60], name: 'Banana Reef', area: 'North Malé Atoll', desc: 'One of the Maldives\' first famous dive sites, named for its curved shape. Overhangs and caves are packed with bluestripe snappers and moray eels, while grey reef sharks and Napoleon wrasse patrol the outer edge.', featured: { grey_reef: 3, napoleon: 3, bluestripe_snapper: 2, giant_moray: 2 } },
    { id: 'maaya_thila', country: 'MV', target: { id: 'whitetip_reef', hint: 'Slim reef sharks with white fin tips rest in caves by day and hunt the thila at night.' }, current: [0.5, 120], name: 'Maaya Thila', area: 'North Ari Atoll', desc: 'A small protected underwater pinnacle ("thila"). One of the world\'s most famous night dives, when whitetip reef sharks hunt in packs among the coral.', featured: { whitetip_reef: 5, green_turtle: 3, giant_moray: 2, grey_reef: 2, lionfish_miles: 2 } },
    { id: 'hanifaru', country: 'MV', target: { id: 'reef_manta', hint: 'Look up: in the plankton-rich bay, huge rays glide and loop near the surface.' }, current: [0.15, 200], name: 'Hanifaru Bay', area: 'Baa Atoll (UNESCO Biosphere Reserve)', desc: 'A small bay that traps plankton in the southwest monsoon (May–November), drawing more than 100 feeding reef mantas at once plus whale sharks. To protect them, visitors may only snorkel here, not scuba dive.', featured: { reef_manta: 12, whale_shark: 6 } },
    { id: 'maamigili', country: 'MV', target: { id: 'whale_shark', hint: 'The biggest fish in the sea cruises the outer reef in the top 20 m.' }, current: [0.3, 90], name: 'South Ari MPA', area: 'Maamigili, South Ari Atoll', desc: 'One of the few places on Earth where whale sharks can be seen year-round — mostly young males cruising the outer reef.', featured: { whale_shark: 15, reef_manta: 2 } },
    { id: 'fuvahmulah', country: 'MV', target: { id: 'tiger', hint: 'A big striped shark that eats almost anything — watch the drop-off in the first 30 m.' }, current: [0.7, 30], name: 'Tiger Zoo', area: 'Fuvahmulah', desc: 'A one-island atoll near the equator where tiger sharks are seen almost daily, along with thresher sharks, great hammerheads and oceanic mantas.', featured: { tiger: 15, pelagic_thresher: 5, great_hammer: 6, oceanic_manta: 5, scalloped_hammer: 2, silvertip: 2 } },
    { id: 'rasdhoo', country: 'MV', target: { id: 'scalloped_hammer', hint: 'Schools of sharks with wide, flat heads rise from the blue off the wall, 20–60 m.' }, current: [0.8, 240], name: 'Hammerhead Point (Madivaru)', area: 'Rasdhoo Atoll', desc: 'Divers drop into the blue at dawn off the outer wall, hoping to see schools of scalloped hammerheads rising from the depths.', featured: { scalloped_hammer: 12, grey_reef: 2, eagle_ray: 2 } },
  ],

  species: [
    // ---------- Sharks ----------
    { id: 'whale_shark', name: 'Whale shark', sci: 'Rhincodon typus', type: 'shark', hab: 'pelagic', depth: [0, 1928], typ: [0, 50], size: 9, sizeTxt: 'Usually 5.5–10 m; up to ~18 m', iucn: 'EN', regions: 'all', ab: 0.02, c: ['#3f5566', '#e9eef0'], f: { whale: 1 }, fact: 'The largest fish in the world. It filter-feeds on plankton and fish eggs, and every whale shark\'s pattern of white spots is unique — researchers identify individuals from divers\' photos.' },
    { id: 'grey_reef', pred: 1, name: 'Grey reef shark', sci: 'Carcharhinus amblyrhynchos', type: 'shark', hab: 'reef', depth: [0, 280], typ: [0, 60], size: 1.9, sizeTxt: 'Usually ~1.9 m; up to ~2.5 m', iucn: 'EN', regions: 'all', ab: 0.12, c: ['#6b7580', '#e6e9ec', '#2a2f35'], f: { tips: '#2a2f35' }, fact: 'Often hunts in groups along drop-offs. When threatened it does a "hunch" display — back arched, fins lowered — a warning divers should respect.' },
    { id: 'whitetip_reef', pred: 1, name: 'Whitetip reef shark', sci: 'Triaenodon obesus', type: 'shark', hab: 'reef', depth: [1, 330], typ: [8, 40], size: 1.6, iucn: 'VU', regions: 'all', ab: 0.12, c: ['#7a7a74', '#e8e6e0', '#ffffff'], f: { tips: '#ffffff', h: 0.08 }, fact: 'Unlike most sharks it can pump water over its gills and rest motionless in caves by day. At night packs hunt, wedging into crevices after fish.' },
    { id: 'blacktip_reef', pred: 1, name: 'Blacktip reef shark', sci: 'Carcharhinus melanopterus', type: 'shark', hab: 'reef', depth: [0, 75], typ: [0, 10], size: 1.6, iucn: 'VU', regions: 'all', ab: 0.12, c: ['#b0a48a', '#f0ece2', '#111111'], f: { tips: '#111111' }, fact: 'Easy to recognise by its black fin tips. Pups patrol lagoons in water barely knee-deep.' },
    { id: 'scalloped_hammer', pred: 1, name: 'Scalloped hammerhead', sci: 'Sphyrna lewini', type: 'shark', hab: 'pelagic', depth: [0, 1043], typ: [15, 80], size: 3, sizeTxt: 'Usually ~3 m; up to 4.3 m', iucn: 'CR', regions: 'all', ab: 0.015, school: [3, 10], c: ['#8a8f86', '#eceae4'], f: { hammer: 1 }, fact: 'Forms large daytime schools around seamounts and reef points, then spreads out to hunt at night. Its wide head spreads out sensors that detect the electric fields of hidden prey.' },
    { id: 'great_hammer', pred: 1, name: 'Great hammerhead', sci: 'Sphyrna mokarran', type: 'shark', hab: 'pelagic', depth: [1, 300], typ: [1, 80], size: 4.5, sizeTxt: 'Usually 3.5–4.5 m; up to ~6 m', iucn: 'CR', regions: ['MV', 'EG', 'ID', 'AU'], ab: 0.008, c: ['#9a9a90', '#eceae4'], f: { hammer: 1, tall: 1 }, fact: 'The largest hammerhead. It specialises in stingrays, pinning them to the seabed with its head, and seems unbothered by their venomous spines.' },
    { id: 'tiger', pred: 1, name: 'Tiger shark', sci: 'Galeocerdo cuvier', type: 'shark', hab: 'pelagic', depth: [0, 1136], typ: [0, 150], size: 4, sizeTxt: 'Usually 3–4 m; up to ~5.5 m', iucn: 'NT', regions: 'all', ab: 0.012, c: ['#6f7a6e', '#e5e5dc', '#3a403a'], f: { stripes: 1, h: 0.1 }, fact: 'Named for the dark stripes of young sharks, which fade with age. It eats almost anything — turtles, seabirds, sea snakes — and its serrated teeth can crack turtle shells.' },
    { id: 'oceanic_whitetip', mood: 'curious', pred: 1, name: 'Oceanic whitetip shark', sci: 'Carcharhinus longimanus', type: 'shark', hab: 'pelagic', depth: [0, 1082], typ: [0, 150], size: 3, sizeTxt: 'Usually 2–3 m; up to ~3.5 m', iucn: 'CR', regions: ['EG', 'MV', 'ID'], ab: 0.006, c: ['#7a7468', '#e8e4dc', '#ffffff'], f: { tips: '#ffffff', longFins: 1 }, fact: 'A bold open-ocean shark with long, rounded, white-tipped fins. Once one of the most common large animals on Earth, its population has collapsed across much of its range because of the fin trade.' },
    { id: 'pelagic_thresher', pred: 1, name: 'Pelagic thresher shark', sci: 'Alopias pelagicus', type: 'shark', hab: 'pelagic', depth: [0, 300], typ: [0, 150], size: 3, sizeTxt: 'Up to ~3.8 m, half of it tail', iucn: 'EN', regions: ['EG', 'MV', 'ID'], ab: 0.006, c: ['#5a6aa0', '#eef0f6'], f: { thresher: 1 }, fact: 'Up to half its length is tail. It whips the tail over its head to stun schooling fish — one of the few sharks known to hunt with its tail.' },
    { id: 'bigeye_thresher', pred: 1, name: 'Bigeye thresher shark', sci: 'Alopias superciliosus', type: 'shark', hab: 'pelagic', depth: [0, 955], typ: [100, 600], size: 3.5, sizeTxt: 'Up to ~4.6 m', iucn: 'VU', regions: 'all', ab: 0.008, c: ['#6a5a7a', '#e8e4ec'], f: { thresher: 1, eyeBig: 1 }, fact: 'Huge upward-facing eyes spot prey silhouetted against the light above. It hangs in cold, dark water by day and rises toward the surface at night.' },
    { id: 'silvertip', pred: 1, name: 'Silvertip shark', sci: 'Carcharhinus albimarginatus', type: 'shark', hab: 'reef', depth: [0, 800], typ: [20, 100], size: 2.5, sizeTxt: 'Usually ~2.5 m; up to 3 m', iucn: 'VU', regions: 'all', ab: 0.03, c: ['#5f6c78', '#e8ecef', '#ffffff'], f: { tips: '#ffffff' }, fact: 'Bright white fin edges make it easy to identify. It is more assertive than grey reef sharks and often dominates them where they meet.' },
    { id: 'tawny_nurse', pred: 1, name: 'Tawny nurse shark', sci: 'Nebrius ferrugineus', type: 'shark', hab: 'reef', depth: [0, 70], typ: [5, 30], size: 3, sizeTxt: 'Up to ~3.2 m', iucn: 'VU', regions: 'all', ab: 0.04, c: ['#a0784a', '#c8a67a'], f: { nurse: 1, h: 0.1 }, fact: 'It sucks prey out of crevices with powerful suction. Mostly active at night; in the Maldives dozens gather at Alimatha for a famous night dive.' },
    { id: 'zebra_shark', name: 'Zebra (leopard) shark', sci: 'Stegostoma tigrinum', type: 'shark', hab: 'reef', depth: [0, 62], typ: [5, 30], size: 2.5, iucn: 'EN', regions: ['EG', 'ID', 'AU', 'PW', 'MV'], ab: 0.02, c: ['#d9c9a0', '#efe6cc', '#3a2e22'], f: { zebra: 1 }, fact: 'Adults are spotted like leopards, but juveniles have zebra-like stripes — hence the confusing name. Females have been recorded having pups without a male (parthenogenesis).' },
    { id: 'wobbegong', name: 'Tasselled wobbegong', sci: 'Eucrossorhinus dasypogon', type: 'shark', hab: 'benthic', lift: 0.06, depth: [0, 40], typ: [2, 40], size: 1.3, sizeTxt: 'Up to ~1.8 m', iucn: 'LC', regions: ['ID', 'AU'], ab: 0.05, c: ['#8a7048', '#c9ad7a', '#4a3a22'], f: { wobbe: 1, h: 0.06 }, fact: 'A master of camouflage: a beard of branching skin tassels hides its outline as it waits on the reef, and it can swallow fish nearly its own size.' },
    { id: 'sixgill', pred: 1, name: 'Bluntnose sixgill shark', sci: 'Hexanchus griseus', type: 'shark', hab: 'pelagic', depth: [0, 2500], typ: [180, 1100], size: 4, sizeTxt: 'Up to ~4.8 m', iucn: 'NT', regions: 'all', ab: 0.02, c: ['#5a5550', '#8a857f'], f: { sixgill: 1, h: 0.1 }, fact: 'A "living fossil" with six gill slits instead of five. Its lineage goes back roughly 200 million years. It rises toward the surface at night to feed.' },
    { id: 'goblin', pred: 1, name: 'Goblin shark', sci: 'Mitsukurina owstoni', type: 'shark', hab: 'pelagic', depth: [100, 1300], typ: [270, 960], size: 3.5, sizeTxt: 'Usually 3–4 m', iucn: 'LC', regions: ['AU'], ab: 0.02, c: ['#d9a0a0', '#f0cccc'], f: { goblin: 1 }, fact: 'Its jaws can shoot forward out of its mouth to snatch prey — one of the fastest jaw strikes known in sharks.' },
    { id: 'megamouth', name: 'Megamouth shark', sci: 'Megachasma pelagios', type: 'shark', hab: 'pelagic', depth: [0, 1000], typ: [10, 200], size: 5, iucn: 'LC', regions: ['ID', 'AU'], ab: 0.004, c: ['#4a4a55', '#dcdce0'], f: { mega: 1, h: 0.12 }, fact: 'Unknown to science until 1976, when one tangled in a US Navy sea anchor off Hawaii. Only a few hundred have ever been recorded. It filter-feeds on krill, following them up at night.' },
    { id: 'cookiecutter', name: 'Cookiecutter shark', sci: 'Isistius brasiliensis', type: 'shark', hab: 'pelagic', depth: [0, 3700], typ: [200, 3500], size: 0.45, iucn: 'LC', regions: 'all', ab: 0.05, c: ['#6a5a4a', '#8a7a6a'], f: { h: 0.08 }, glow: { c: '#6fd6ff', s: 'belly' }, fact: 'It latches onto much larger animals — whales, tuna, even submarines — and twists out a round plug of flesh. Its belly glows to hide its silhouette from below.' },

    // ---------- Rays ----------
    { id: 'reef_manta', mood: 'curious', name: 'Reef manta ray', sci: 'Mobula alfredi', type: 'ray', hab: 'pelagic', depth: [0, 400], typ: [0, 40], size: 3.5, sizeTxt: 'Wingspan usually 3–3.5 m; up to 5.5 m', iucn: 'VU', regions: 'all', ab: 0.05, c: ['#1e2228', '#f4f4f4'], f: { manta: 1 }, fact: 'Mantas have one of the largest brains relative to body size of any fish. They visit "cleaning stations" where small wrasse pick off parasites, and each one\'s belly spots are unique — used for photo-ID.' },
    { id: 'oceanic_manta', name: 'Oceanic manta ray', sci: 'Mobula birostris', type: 'ray', hab: 'pelagic', depth: [0, 1000], typ: [0, 120], size: 5, sizeTxt: 'Wingspan up to ~7 m', iucn: 'EN', regions: ['ID', 'AU', 'MV'], ab: 0.008, c: ['#15181c', '#f4f4f4'], f: { manta: 1 }, fact: 'The largest ray on Earth. Unlike reef mantas it roams the open ocean, and it has been tracked diving beyond 1,000 m.' },
    { id: 'eagle_ray', name: 'Ocellated eagle ray', sci: 'Aetobatus ocellatus', type: 'ray', hab: 'pelagic', depth: [1, 80], typ: [1, 40], size: 2, sizeTxt: 'Wingspan up to ~3 m', iucn: 'EN', regions: 'all', ab: 0.03, school: [1, 4], c: ['#2a3040', '#f0f0f0', '#ffffff'], f: { eagle: 1 }, fact: 'A graceful ray covered in white spots. It digs clams and snails from the sand with its duck-like snout and crushes their shells with plate-like teeth.' },
    { id: 'ribbontail_ray', name: 'Bluespotted ribbontail ray', sci: 'Taeniura lymma', type: 'ray', hab: 'benthic', lift: 0.05, depth: [0, 25], size: 0.7, sizeTxt: 'Disc ~35 cm; ~70 cm with tail', iucn: 'LC', regions: 'all', ab: 0.08, c: ['#c6a46a', '#ffffff', '#2a9dff'], f: { sting: 1 }, fact: 'Its electric-blue spots warn predators about the venomous barbs on its tail. At high tide groups move into the shallows to hunt crabs and worms in the sand.' },

    // ---------- Reptiles & mammals ----------
    { id: 'green_turtle', mood: 'curious', name: 'Green sea turtle', sci: 'Chelonia mydas', type: 'turtle', hab: 'reef', depth: [0, 140], typ: [0, 40], size: 1.1, sizeTxt: 'Shell ~0.8–1.2 m', iucn: 'EN', regions: 'all', ab: 0.06, c: ['#6a5a3a', '#a08a5a', '#d8c89a'], fact: 'Named for the green colour of its fat, not its shell. Adults graze seagrass and algae, and females return to nest on the beach where they hatched.' },
    { id: 'hawksbill', mood: 'curious', name: 'Hawksbill turtle', sci: 'Eretmochelys imbricata', type: 'turtle', hab: 'reef', depth: [0, 90], typ: [0, 30], size: 0.9, sizeTxt: 'Shell up to ~1 m', iucn: 'CR', regions: 'all', ab: 0.04, c: ['#7a4a22', '#c08a4a', '#e8c89a'], f: { hawk: 1 }, fact: 'Its narrow, hawk-like beak reaches into reef crevices for sponges, including ones toxic to most animals. Its patterned shell was once sold as "tortoiseshell".' },
    { id: 'krait', name: 'Banded sea krait', sci: 'Laticauda colubrina', type: 'eel', hab: 'reef', depth: [0, 60], typ: [0, 15], size: 1.2, iucn: 'LC', regions: ['ID', 'PW'], ab: 0.04, kind: 'Sea snake (reptile)', c: ['#6a8ab8', '#141414', '#e8e0a0'], f: { bands: 1 }, fact: 'Highly venomous but docile. It hunts eels on the reef, then returns to land to digest, shed its skin and lay eggs. It must surface to breathe air.' },
    { id: 'olive_seasnake', name: 'Olive sea snake', sci: 'Aipysurus laevis', type: 'eel', hab: 'reef', depth: [0, 45], size: 1.5, sizeTxt: 'Up to ~2 m', iucn: 'LC', regions: ['AU'], ab: 0.05, kind: 'Sea snake (reptile)', c: ['#8a7a4a', '#b0a070', '#6a5a30'], fact: 'Can stay underwater for up to two hours, partly by absorbing oxygen through its skin. Curious ones often swim right up to divers.' },
    { id: 'dugong', name: 'Dugong', sci: 'Dugong dugon', type: 'whale', hab: 'reef', depth: [0, 37], typ: [1, 20], size: 3, iucn: 'VU', regions: ['EG', 'AU', 'ID', 'PW'], ab: 0.01, c: ['#a89a8c', '#c8bcb0'], f: { dugong: 1 }, fact: 'A cousin of elephants and the only strictly marine plant-eating mammal. An adult can eat up to about 40 kg of seagrass a day.' },
    { id: 'spinner', mood: 'curious', name: 'Spinner dolphin', sci: 'Stenella longirostris', type: 'whale', hab: 'pelagic', depth: [0, 300], typ: [0, 50], size: 2, iucn: 'LC', regions: 'all', ab: 0.02, school: [4, 9], c: ['#6a7a8a', '#dde4ea'], f: { dolphin: 1 }, fact: 'Famous for leaping and spinning up to seven times in one jump. Pods rest in calm lagoons by day and hunt in deep water at night.' },
    { id: 'humpback', name: 'Humpback whale', sci: 'Megaptera novaeangliae', type: 'whale', hab: 'pelagic', depth: [0, 600], typ: [0, 100], size: 15, sizeTxt: 'Up to ~16 m', iucn: 'LC', regions: ['AU'], ab: 0.004, c: ['#2a2e36', '#dfe3e8'], f: { humpback: 1 }, fact: 'Makes one of the longest migrations of any mammal, between Antarctic feeding grounds and warm breeding waters. Males sing complex songs that change year by year.' },
    { id: 'sperm', name: 'Sperm whale', sci: 'Physeter macrocephalus', type: 'whale', hab: 'pelagic', depth: [0, 2250], typ: [300, 1200], size: 16, sizeTxt: 'Males up to ~16–20 m', iucn: 'VU', regions: ['MV', 'ID', 'AU', 'PW'], ab: 0.004, c: ['#4a4a4e', '#6a6a70'], f: { sperm: 1 }, fact: 'Has the largest brain of any animal. It dives for an hour or more to 1,000–2,000 m to hunt squid — sucker scars on its skin record the battles.' },
    { id: 'blue_whale', name: 'Blue whale (pygmy)', sci: 'Balaenoptera musculus', type: 'whale', hab: 'pelagic', depth: [0, 315], typ: [0, 100], size: 22, sizeTxt: 'Pygmy blues up to ~24 m; blue whales up to ~30 m', iucn: 'EN', regions: ['MV', 'ID', 'AU'], ab: 0.003, c: ['#5a7085', '#a8b8c8'], f: { blue: 1 }, fact: 'The largest animal known to have ever lived. Pygmy blue whales, a smaller subspecies, pass the Maldives, Sri Lanka and Indonesia. Their calls travel hundreds of kilometres.' },

    // ---------- Reef fish ----------
    { id: 'napoleon', mood: 'curious', name: 'Napoleon (humphead) wrasse', sci: 'Cheilinus undulatus', type: 'fish', hab: 'reef', depth: [1, 100], typ: [2, 60], size: 1.5, sizeTxt: 'Up to ~2.3 m', iucn: 'EN', regions: 'all', ab: 0.05, c: ['#2f8f83', '#8fd0c0', '#1d5e62'], f: { h: 0.42, hump: 1, tail: 'round', pattern: 'lines' }, fact: 'One of the largest reef fish, with a bulging forehead and maze-like face markings unique to each fish. It is one of the few animals that eats crown-of-thorns starfish and toxic boxfish.' },
    { id: 'giant_trevally', pred: 1, name: 'Giant trevally', sci: 'Caranx ignobilis', type: 'fish', hab: 'reef', depth: [0, 188], typ: [5, 60], size: 1.2, sizeTxt: 'Up to ~1.7 m', iucn: 'LC', regions: 'all', ab: 0.06, school: [1, 4], c: ['#8a99a3', '#dfe6ea', '#39454d'], f: { h: 0.42 }, fact: 'A powerful predator that hunts in packs along reef edges. In the Seychelles, giant trevally have been filmed leaping out of the water to catch young seabirds.' },
    { id: 'bluefin_trevally', pred: 1, name: 'Bluefin trevally', sci: 'Caranx melampygus', type: 'fish', hab: 'reef', depth: [0, 190], typ: [0, 40], size: 0.8, sizeTxt: 'Up to ~1.2 m', iucn: 'LC', regions: 'all', ab: 0.08, school: [1, 5], c: ['#4a86b8', '#c9dcea', '#1f3050'], f: { h: 0.4, pattern: 'dots' }, fact: 'Often shadows hunting moray eels or octopuses, grabbing any fish they flush out of hiding.' },
    { id: 'barracuda', pred: 1, name: 'Great barracuda', sci: 'Sphyraena barracuda', type: 'fish', hab: 'reef', depth: [0, 100], typ: [1, 30], size: 1.4, sizeTxt: 'Up to ~2 m', iucn: 'LC', regions: 'all', ab: 0.05, c: ['#9fb1bb', '#e8eef2', '#2e3e48'], f: { h: 0.16, pattern: 'blotch', teeth: 1 }, fact: 'An ambush predator with fang-like teeth that attacks in fast bursts. Large ones can carry ciguatera toxin built up through the reef food chain.' },
    { id: 'chevron_barracuda', pred: 1, name: 'Chevron barracuda', sci: 'Sphyraena qenie', type: 'fish', hab: 'reef', depth: [1, 50], typ: [5, 40], size: 0.9, iucn: 'LC', regions: 'all', ab: 0.08, school: [25, 50], c: ['#a7b7c2', '#e8eef2', '#55646e'], f: { h: 0.15, pattern: 'chevrons' }, fact: 'Forms swirling "barracuda tornadoes" of hundreds of fish that hang in the current by day and split up to hunt at night.' },
    { id: 'bluestripe_snapper', name: 'Bluestripe snapper', sci: 'Lutjanus kasmira', type: 'fish', hab: 'reef', depth: [3, 265], typ: [3, 60], size: 0.3, iucn: 'LC', regions: 'all', ab: 0.35, school: [25, 45], c: ['#f2c21b', '#5ab4ff', '#f2c21b'], f: { h: 0.36, pattern: 'hstripes' }, fact: 'Gathers in dense yellow-and-blue schools by day. Introduced to Hawaii in the 1950s, it became one of the most common reef fish there.' },
    { id: 'anthias', name: 'Lyretail anthias', sci: 'Pseudanthias squamipinnis', type: 'fish', hab: 'reef', depth: [0, 55], typ: [0, 30], size: 0.15, iucn: 'LC', regions: 'all', ab: 0.8, school: [20, 40], c: ['#ff8a3d', '#ffb07a', '#c43bb0'], f: { h: 0.36, tail: 'lyre' }, fact: 'Orange swarms of anthias live in harems led by one magenta male. If the male dies, the dominant female changes sex and takes his place.' },
    { id: 'moorish_idol', name: 'Moorish idol', sci: 'Zanclus cornutus', type: 'fish', hab: 'reef', depth: [1, 180], typ: [3, 30], size: 0.2, iucn: 'LC', regions: 'all', ab: 0.2, school: [1, 3], c: ['#f5f0e0', '#1a1a1a', '#f5c518'], f: { h: 0.85, dorsal: 'streamer', pattern: 'vbands' }, fact: 'The only living species in its family, Zanclidae. It feeds mostly on sponges, and despite looking alike, it is not closely related to bannerfish.' },
    { id: 'emperor_angel', name: 'Emperor angelfish', sci: 'Pomacanthus imperator', type: 'fish', hab: 'reef', depth: [1, 100], typ: [3, 30], size: 0.35, iucn: 'LC', regions: 'all', ab: 0.15, c: ['#1f3fa8', '#f7d11e', '#0c1a44'], f: { h: 0.62, pattern: 'hstripes', tail: 'round', tailc: '#f7d11e' }, fact: 'Juveniles are dark blue with white rings — so different from adults they were once thought to be another species. It makes loud knocking sounds when disturbed.' },
    { id: 'regal_angel', name: 'Regal angelfish', sci: 'Pygoplites diacanthus', type: 'fish', hab: 'reef', depth: [1, 80], typ: [3, 30], size: 0.25, iucn: 'LC', regions: 'all', ab: 0.12, c: ['#f39c1e', '#2b3f9e', '#ffffff'], f: { h: 0.6, pattern: 'vbands', tail: 'round' }, fact: 'Its bright bars are edged in blue and white. It is a picky eater that feeds almost entirely on sponges and sea squirts, which makes it hard to keep in aquariums.' },
    { id: 'oriental_sweetlips', name: 'Oriental sweetlips', sci: 'Plectorhinchus vittatus', type: 'fish', hab: 'reef', depth: [2, 25], size: 0.5, sizeTxt: 'Up to ~86 cm', iucn: 'LC', regions: ['MV', 'ID', 'AU', 'PW'], ab: 0.12, school: [1, 6], c: ['#f4f1e8', '#1a1a1a', '#f5d215'], f: { h: 0.4, pattern: 'hstripes', tailc: '#f5d215' }, fact: 'Adults rest in small groups under overhangs by day. Juveniles are brown with white blotches and swim with an exaggerated wriggle thought to mimic toxic flatworms.' },
    { id: 'powder_blue', name: 'Powder blue tang', sci: 'Acanthurus leucosternon', type: 'fish', hab: 'reef', depth: [0, 25], size: 0.23, iucn: 'LC', regions: ['MV', 'ID'], ab: 0.3, school: [2, 8], c: ['#3aa0e8', '#1a1a1a', '#f5e11a'], f: { h: 0.6, pattern: 'face', tail: 'lunate' }, fact: 'Like all surgeonfish it has a scalpel-sharp spine at the base of its tail. Large feeding groups overwhelm territorial fish to graze their algae.' },
    { id: 'sohal', name: 'Sohal surgeonfish', sci: 'Acanthurus sohal', type: 'fish', hab: 'reef', depth: [0, 10], size: 0.4, iucn: 'LC', regions: ['EG'], ab: 0.3, c: ['#4a5e79', '#1e2a38', '#f79a1e'], f: { h: 0.55, pattern: 'hlines', tail: 'lunate' }, fact: 'Found only in the Red Sea and Arabian region. Males fiercely guard algae "gardens" on the reef top and will charge intruders — even divers.' },
    { id: 'palette_tang', name: 'Palette surgeonfish (blue tang)', sci: 'Paracanthurus hepatus', type: 'fish', hab: 'reef', depth: [2, 40], size: 0.25, iucn: 'LC', regions: ['MV', 'ID', 'AU', 'PW'], ab: 0.15, school: [1, 5], c: ['#1c52d6', '#141414', '#f5d400'], f: { h: 0.5, pattern: 'palette', tailc: '#f5d400', tail: 'lunate' }, fact: 'The real-life "Dory". When threatened it wedges itself into branching coral and defends itself with the sharp spine near its tail.' },
    { id: 'bumphead', name: 'Bumphead parrotfish', sci: 'Bolbometopon muricatum', type: 'fish', hab: 'reef', depth: [1, 30], size: 1.2, sizeTxt: 'Up to ~1.3 m', iucn: 'VU', regions: 'all', ab: 0.04, school: [3, 10], c: ['#5e8f7a', '#9fc1ae', '#b9cfa0'], f: { h: 0.5, hump: 2, tail: 'lunate' }, fact: 'The largest parrotfish. Herds head-butt and bite chunks off coral; a single adult can turn around 5 tonnes of reef into sand each year.' },
    { id: 'masked_butterfly', name: 'Masked (bluecheek) butterflyfish', sci: 'Chaetodon semilarvatus', type: 'fish', hab: 'reef', depth: [3, 20], size: 0.23, iucn: 'LC', regions: ['EG'], ab: 0.2, school: [1, 2], c: ['#f5d21b', '#2b6fb8', '#f08c1b'], f: { h: 0.85, pattern: 'mask' }, fact: 'Found only in the Red Sea and Gulf of Aden. Pairs often hover motionless in the shade under table corals during the day.' },
    { id: 'threadfin_butterfly', name: 'Threadfin butterflyfish', sci: 'Chaetodon auriga', type: 'fish', hab: 'reef', depth: [1, 60], size: 0.23, iucn: 'LC', regions: 'all', ab: 0.2, school: [1, 2], c: ['#f5f2ea', '#1a1a1a', '#f5c518'], f: { h: 0.8, pattern: 'butterfly' }, fact: 'Butterflyfish usually live in long-term pairs. The dark band hiding its eye and the dark spot near its tail may confuse predators about which way it will flee.' },
    { id: 'titan_trigger', name: 'Titan triggerfish', sci: 'Balistoides viridescens', type: 'fish', hab: 'reef', depth: [1, 50], size: 0.6, sizeTxt: 'Up to ~75 cm', iucn: 'LC', regions: 'all', ab: 0.05, c: ['#6a7a5c', '#e0c090', '#2a3a30'], f: { h: 0.6, pattern: 'scales', tail: 'round' }, fact: 'Guards its nest inside a cone-shaped territory that widens up to the surface. If one charges you, swim away sideways — not up.' },
    { id: 'clown_trigger', name: 'Clown triggerfish', sci: 'Balistoides conspicillum', type: 'fish', hab: 'reef', depth: [1, 75], size: 0.4, iucn: 'LC', regions: ['MV', 'ID', 'AU', 'PW'], ab: 0.05, c: ['#141a2a', '#ffffff', '#f5c518'], f: { h: 0.55, pattern: 'bigspots', tail: 'round' }, fact: 'Triggerfish get their name from a locking dorsal spine: they wedge into a crevice and lock the spine upright so predators can\'t pull them out.' },
    { id: 'giant_moray', name: 'Giant moray', sci: 'Gymnothorax javanicus', type: 'eel', hab: 'benthic', lift: 0.03, depth: [0, 50], size: 2, sizeTxt: 'Up to ~3 m', iucn: 'LC', regions: 'all', ab: 0.08, c: ['#6a6a3a', '#8a8a4a', '#2a2a1a'], f: { moray: 1 }, fact: 'The gaping that looks threatening is just breathing. Morays have a second set of jaws in their throat that shoot forward to drag prey down, and they sometimes hunt together with groupers.' },
    { id: 'lionfish_miles', pred: 1, name: 'Devil firefish (lionfish)', sci: 'Pterois miles', type: 'fish', hab: 'reef', depth: [1, 60], size: 0.35, iucn: 'LC', regions: ['MV', 'EG'], ab: 0.1, c: ['#c4412e', '#f5e9dc', '#7a1f14'], f: { h: 0.4, dorsal: 'spiky', pattern: 'vbands' }, fact: 'Its venomous spines deter predators. In the Mediterranean it has become a fast-spreading invader after entering through the Suez Canal.' },
    { id: 'lionfish_volitans', pred: 1, name: 'Red lionfish', sci: 'Pterois volitans', type: 'fish', hab: 'reef', depth: [1, 55], size: 0.38, iucn: 'LC', regions: ['ID', 'AU', 'PW'], ab: 0.1, c: ['#b8452e', '#f5e9dc', '#6a1f14'], f: { h: 0.4, dorsal: 'spiky', pattern: 'vbands' }, fact: 'Native to the Indo-Pacific, it is one of the most damaging invasive fish in the Atlantic and Caribbean, where it has few natural predators.' },
    { id: 'stonefish', name: 'Reef stonefish', sci: 'Synanceia verrucosa', type: 'fish', hab: 'benthic', lift: 0.18, depth: [0, 30], size: 0.35, iucn: 'LC', regions: 'all', ab: 0.05, c: ['#6b5a4a', '#8a7a64', '#3d3228'], f: { h: 0.55, pattern: 'warts', tail: 'round' }, fact: 'The most venomous fish known. It looks exactly like a lump of rock, and its 13 dorsal spines can inject venom that can kill a person without treatment.' },
    { id: 'frogfish', name: 'Giant frogfish', sci: 'Antennarius commerson', type: 'fish', hab: 'benthic', lift: 0.3, depth: [0, 70], size: 0.35, iucn: 'LC', regions: 'all', ab: 0.03, c: ['#e3b23c', '#f0cf6a', '#8a5a1a'], f: { h: 0.8, lure: 1, tail: 'round' }, fact: 'A spine tipped with a wiggling lure attracts prey, which it swallows in about 6 milliseconds — one of the fastest strikes of any vertebrate.' },
    { id: 'leaf_scorpion', name: 'Leaf scorpionfish', sci: 'Taenianotus triacanthus', type: 'fish', hab: 'benthic', lift: 0.35, depth: [1, 135], size: 0.1, iucn: 'LC', regions: 'all', ab: 0.04, c: ['#f2c7d0', '#e89aac', '#b0485f'], f: { h: 0.9, dorsal: 'sail', tail: 'round' }, fact: 'Sways side to side like a dead leaf in the surge. It sheds its skin every couple of weeks.' },
    { id: 'giant_grouper', mood: 'curious', pred: 1, name: 'Giant grouper', sci: 'Epinephelus lanceolatus', type: 'fish', hab: 'reef', depth: [0, 100], size: 2, sizeTxt: 'Up to ~2.7 m, 400 kg', iucn: 'VU', regions: 'all', ab: 0.015, c: ['#5a5a3a', '#d8cf8e', '#2a2a1a'], f: { h: 0.45, pattern: 'blotch', tail: 'round' }, fact: 'The largest bony fish found on coral reefs. Like many groupers, it starts life as a female and may later become male.' },
    { id: 'potato_cod', mood: 'curious', pred: 1, name: 'Potato cod', sci: 'Epinephelus tukula', type: 'fish', hab: 'reef', depth: [10, 150], typ: [10, 40], size: 1.5, sizeTxt: 'Up to ~2 m', iucn: 'LC', regions: ['AU'], ab: 0.02, c: ['#d9d2c0', '#6a4a2e', '#3a2a1a'], f: { h: 0.42, pattern: 'blotch', tail: 'round' }, fact: 'A giant grouper named for its potato-shaped blotches. At the Cod Hole these fish have been approaching divers for decades.' },
    { id: 'coelacanth', name: 'Indonesian coelacanth', sci: 'Latimeria menadoensis', type: 'fish', hab: 'reef', depth: [100, 250], typ: [140, 200], size: 1.4, iucn: 'VU', regions: ['ID'], ab: 0.004, c: ['#2a4d8a', '#e8eef8', '#1a2a50'], f: { h: 0.3, lobed: 1, pattern: 'whitespots', tail: 'round' }, fact: 'Coelacanths were thought extinct for 66 million years until one was caught in 1938. This second species was found in 1997 when a biologist spotted one at a fish market in Manado. Its lobed fins move like limbs.' },

    // ---------- Anemonefish (live on anemones) ----------
    { id: 'nigripes', name: 'Maldives anemonefish', sci: 'Amphiprion nigripes', type: 'fish', hab: 'reef', host: 'anemone', depth: [2, 25], size: 0.11, iucn: 'LC', regions: ['MV'], c: ['#f39a3c', '#ffffff', '#111111'], f: { h: 0.5, tail: 'round', pattern: 'bands', n: 1 }, fact: 'Found only around the Maldives and Sri Lanka. Like all clownfish, a mucus coat protects it from its anemone\'s stings — and all start life as males; the biggest becomes the female.' },
    { id: 'bicinctus', name: 'Red Sea anemonefish', sci: 'Amphiprion bicinctus', type: 'fish', hab: 'reef', host: 'anemone', depth: [1, 30], size: 0.14, iucn: 'LC', regions: ['EG'], c: ['#f08a1c', '#ffffff', '#222222'], f: { h: 0.5, tail: 'round', pattern: 'bands', n: 2 }, fact: 'Found in the Red Sea and the Chagos Islands. It defends its anemone boldly and will nip at divers who get too close.' },
    { id: 'ocellaris', name: 'Ocellaris clownfish', sci: 'Amphiprion ocellaris', type: 'fish', hab: 'reef', host: 'anemone', depth: [1, 15], size: 0.11, iucn: 'LC', regions: ['ID', 'AU'], c: ['#ff7a1a', '#ffffff', '#111111'], f: { h: 0.5, tail: 'round', pattern: 'bands', n: 3, edge: 1 }, fact: 'The fish that inspired "Nemo". The anemone protects it, and in return it chases off butterflyfish that would eat the anemone.' },
    { id: 'percula', name: 'Orange clownfish', sci: 'Amphiprion percula', type: 'fish', hab: 'reef', host: 'anemone', depth: [1, 15], size: 0.11, iucn: 'LC', regions: ['AU', 'ID'], c: ['#ff6a10', '#ffffff', '#111111'], f: { h: 0.5, tail: 'round', pattern: 'bands', n: 3, edge: 2 }, fact: 'Almost identical to the ocellaris clownfish but with thicker black edges on its white bands. Only one breeding pair lives in each anemone; the others wait their turn.' },
    { id: 'clarkii', name: 'Clark\'s anemonefish', sci: 'Amphiprion clarkii', type: 'fish', hab: 'reef', host: 'anemone', depth: [1, 55], size: 0.15, iucn: 'LC', regions: ['MV', 'ID', 'AU', 'PW'], c: ['#2a2016', '#ffffff', '#f5a01e'], f: { h: 0.5, tail: 'round', pattern: 'bands', n: 3, tailc: '#f5a01e' }, fact: 'The most widespread anemonefish. It lives with all ten host anemone species — more than any other clownfish.' },

    // ---------- Invertebrates of the reef ----------
    { id: 'cuttlefish', mood: 'curious', name: 'Broadclub cuttlefish', sci: 'Sepia latimanus', type: 'cuttle', hab: 'reef', depth: [0, 30], size: 0.5, iucn: 'DD', regions: ['MV', 'ID', 'AU', 'PW'], ab: 0.05, c: ['#b8a58a', '#e8dcc8', '#6a5a4a'], fact: 'Changes colour and skin texture in a fraction of a second, even rippling bands of colour across its body to mesmerise prey.' },
    { id: 'day_octopus', name: 'Day octopus', sci: 'Octopus cyanea', type: 'octopus', hab: 'reef', depth: [0, 150], typ: [0, 25], size: 0.8, sizeTxt: '~80 cm arm span', iucn: 'LC', regions: 'all', ab: 0.05, c: ['#8a5a3a', '#c89a7a'], fact: 'Unusually for an octopus, it hunts by day. Groupers and trevallies often follow it to snap up anything it flushes out.' },
    { id: 'mimic_octopus', name: 'Mimic octopus', sci: 'Thaumoctopus mimicus', type: 'octopus', hab: 'reef', depth: [2, 37], size: 0.6, iucn: 'NE', regions: ['ID', 'AU'], ab: 0.01, c: ['#c8a47a', '#3a2a1a'], f: { striped: 1 }, fact: 'Discovered in 1998 off Sulawesi. It impersonates lionfish, sea snakes and flatfish to fool predators — the first animal found to mimic several different species.' },
    { id: 'flamboyant_cuttle', name: 'Flamboyant cuttlefish', sci: 'Metasepia pfefferi', type: 'cuttle', hab: 'benthic', lift: 0.25, depth: [3, 86], size: 0.08, iucn: 'DD', regions: ['ID', 'AU'], ab: 0.01, c: ['#7a3a8a', '#f5d21b', '#e83a3a'], fact: 'Walks along the seabed on its arms instead of swimming, flashing purple, yellow and red. Its flesh has been found to be toxic — rare for a cephalopod.' },
    { id: 'pygmy_seahorse', name: 'Pygmy seahorse', sci: 'Hippocampus bargibanti', type: 'seahorse', hab: 'benthic', lift: 0.5, depth: [16, 40], size: 0.024, iucn: 'DD', regions: ['ID', 'AU', 'PW'], ab: 0.02, c: ['#e89aac', '#f5c8d0', '#c0506a'], fact: 'About 2 cm long, it spends its life on a single sea fan and matches its colour and bumps so well that it was only discovered when a sea fan was collected for a museum.' },
    { id: 'spanish_dancer', name: 'Spanish dancer', sci: 'Hexabranchus sanguineus', type: 'nudi', hab: 'benthic', lift: 0.1, depth: [0, 50], size: 0.3, sizeTxt: 'Up to ~40 cm', iucn: 'NE', regions: 'all', ab: 0.03, kind: 'Nudibranch (sea slug)', c: ['#d8202c', '#ffffff', '#ffb0a0'], fact: 'One of the largest nudibranchs. When disturbed it unfurls its red mantle and swims with flamenco-like ripples. Its egg ribbons look like red roses.' },
    { id: 'cots', name: 'Crown-of-thorns starfish', sci: 'Acanthaster sp.', type: 'star', hab: 'benthic', lift: 0.02, depth: [0, 60], size: 0.35, iucn: 'NE', regions: 'all', ab: 0.04, c: ['#8a3a5a', '#d86a4a', '#f5c8a0'], fact: 'It eats coral by pushing its stomach out over the coral. Population outbreaks have killed large areas of the Great Barrier Reef.' },
    { id: 'small_clam', name: 'Small giant clam', sci: 'Tridacna maxima', type: 'clam', hab: 'benthic', lift: 0.02, depth: [0, 20], size: 0.3, iucn: 'LC', regions: 'all', ab: 0.5, c: ['#2a7ad8', '#4ad8c8', '#d8d0b8'], fact: 'Its mantle holds algae that feed it sugar made from sunlight, and the shimmering colours act like sunscreen. Every mantle pattern is different.' },
    { id: 'giant_clam', name: 'Giant clam', sci: 'Tridacna gigas', type: 'clam', hab: 'benthic', lift: 0.02, depth: [0, 20], size: 1.1, sizeTxt: 'Over 1 m wide, 200+ kg', iucn: 'VU', regions: ['ID', 'AU', 'PW'], ab: 0.05, c: ['#6a8a4a', '#3a7ab8', '#e0d8c0'], fact: 'The world\'s largest clam, living 100 years or more. Despite old legends, it closes far too slowly to trap a diver.' },

    // ---------- Corals, anemones, sponges (fixed to the reef) ----------
    { id: 'brain_coral', tints: ['#ffffff', '#d0ffc0', '#ffe0a0', '#c0c0ff'], name: 'Brain coral', sci: 'Platygyra daedalea', type: 'brain', hab: 'benthic', depth: [0, 30], typ: [1, 20], size: 1, iucn: 'LC', regions: 'all', ab: 1.2, kind: 'Hard coral', c: ['#b8a45a', '#7a6a2a'], fact: 'Each groove holds a row of coral polyps. Brain corals grow slowly, and big domes can be several hundred years old.' },
    { id: 'table_coral', tints: ['#ffffff', '#c0e0ff', '#e0ffc0', '#ffd0e0'], name: 'Table coral', sci: 'Acropora hyacinthus', type: 'table', hab: 'benthic', depth: [1, 20], size: 1.6, iucn: 'NT', regions: 'all', ab: 0.9, kind: 'Hard coral', c: ['#9a8a6a', '#c8b88a'], fact: 'Its flat plates catch as much sunlight as possible for the algae living in its tissue. It grows fast but is among the first corals to bleach when the sea overheats.' },
    { id: 'staghorn', tints: ['#ffffff', '#c0d8ff', '#ffe0b0', '#e0c0ff'], name: 'Staghorn coral', sci: 'Acropora muricata', type: 'branch', hab: 'benthic', depth: [0, 25], typ: [1, 15], size: 1.2, iucn: 'NT', regions: 'all', ab: 1.5, kind: 'Hard coral', c: ['#c8a47a', '#9ad0e8'], fact: 'One of the fastest-growing corals — branches can grow 10–20 cm a year — making shelter for countless small fish.' },
    { id: 'mushroom_coral', name: 'Mushroom coral', sci: 'Fungia fungites', type: 'mushroom', hab: 'benthic', depth: [1, 35], size: 0.25, iucn: 'NT', regions: 'all', ab: 0.7, kind: 'Hard coral', c: ['#b89a7a', '#e8d0b0'], fact: 'Unlike most corals it is one giant polyp and not attached to the reef: it can slowly move and even flip itself right side up.' },
    { id: 'magnificent_anemone', tints: ['#ffffff', '#ffb0c0', '#c0ffd0', '#e0c0ff'], name: 'Magnificent sea anemone', sci: 'Heteractis magnifica', type: 'anemone', hab: 'benthic', depth: [1, 20], size: 0.6, iucn: 'NE', regions: 'all', ab: 0.6, kind: 'Sea anemone', c: ['#c83a6a', '#e8d898'], fact: 'An anemone, not a coral. It hosts clownfish and may live for decades. Its tentacles carry stinging cells that fire on contact.' },
    { id: 'sea_fan', tints: ['#ffffff', '#ffd060', '#ff9080', '#ffe0a0'], name: 'Giant sea fan', sci: 'Annella mollis', type: 'fan', hab: 'benthic', depth: [5, 50], typ: [10, 40], size: 1.8, iucn: 'NE', regions: 'all', ab: 0.8, kind: 'Soft coral (gorgonian)', c: ['#d86a3a', '#f0a070'], fact: 'Sea fans grow across the current to strain plankton from the water. Pygmy seahorses often hide on them.' },
    { id: 'soft_coral', tints: ['#ffffff', '#ffb0d0', '#d0a0ff', '#ffc080', '#ff8080'], name: 'Carnation tree coral', sci: 'Dendronephthya sp.', type: 'softcoral', hab: 'benthic', depth: [3, 100], typ: [10, 40], size: 0.7, iucn: 'NE', regions: 'all', ab: 1.2, kind: 'Soft coral', c: ['#e84a8a', '#f5e0e8', '#f07ab0'], fact: 'It has no stony skeleton and inflates with water to feed in the current, deflating when the current stops.' },
    { id: 'barrel_sponge', tints: ['#ffffff', '#ffc8b0', '#d8c0b0'], name: 'Giant barrel sponge', sci: 'Xestospongia testudinaria', type: 'sponge', hab: 'benthic', depth: [5, 60], typ: [10, 40], size: 1.1, iucn: 'NE', regions: 'all', ab: 0.5, kind: 'Sponge', c: ['#8a5a4a', '#b07a62'], fact: 'Can grow big enough for a diver to sit in and may live for centuries, pumping huge volumes of water through its body every day.' },
    { id: 'black_coral', name: 'Black coral', sci: 'Antipatharia', type: 'black', hab: 'benthic', depth: [20, 8600], typ: [30, 300], size: 1.4, iucn: 'NE', regions: 'all', ab: 0.3, kind: 'Coral (antipatharian)', c: ['#e8e0c0', '#f5a050'], fact: 'Named for its black skeleton, not its living colour. Some deep black coral colonies are over 4,000 years old — among the oldest living animals on Earth.' },

    // ---------- Deep reef & twilight zone ----------
    { id: 'nautilus', name: 'Chambered nautilus', sci: 'Nautilus pompilius', type: 'nautilus', hab: 'reef', depth: [60, 750], typ: [150, 400], size: 0.2, iucn: 'NE', regions: ['ID', 'AU'], ab: 0.05, kind: 'Cephalopod', c: ['#f5ece0', '#9a4a1a'], fact: 'A relative of octopus and squid that kept its shell. It controls buoyancy by moving fluid in and out of gas-filled chambers, and rises shallower at night. Its shell implodes below about 800 m.' },
    { id: 'palau_nautilus', name: 'Palau nautilus', sci: 'Nautilus belauensis', type: 'nautilus', hab: 'reef', depth: [60, 700], typ: [150, 300], size: 0.23, iucn: 'NE', regions: ['PW'], ab: 0.05, kind: 'Cephalopod', c: ['#f5ece0', '#8a3a1a'], fact: 'The largest nautilus species, found only around Palau. Nautiluses have up to about 90 tentacles with no suckers.' },
    { id: 'venus_basket', name: 'Venus\' flower basket', sci: 'Euplectella aspergillum', type: 'glass', hab: 'benthic', depth: [100, 1000], typ: [150, 700], size: 0.3, iucn: 'NE', regions: ['ID', 'PW'], ab: 0.15, kind: 'Glass sponge', c: ['#e8f0f0', '#c0d8d8'], fact: 'A sponge with a skeleton of glass lace. A pair of shrimp often move in when young and grow too big to leave — so in Japan it is a traditional wedding gift.' },
    { id: 'swordfish', pred: 1, name: 'Swordfish', sci: 'Xiphias gladius', type: 'fish', hab: 'pelagic', depth: [0, 2878], typ: [0, 600], size: 3, sizeTxt: 'Usually ~3 m; up to ~4.5 m', iucn: 'LC', regions: ['MV', 'ID', 'AU', 'PW'], ab: 0.006, c: ['#3a4a6a', '#c0c8d8', '#2a3048'], f: { h: 0.2, bill: 1, tail: 'lunate', dorsal: 'tall' }, fact: 'Special heater tissue warms its eyes and brain so it can see sharply in cold, dark water while hunting squid. It slashes prey with its flat "sword".' },
    { id: 'sunfish', name: 'Ocean sunfish (mola)', sci: 'Mola mola', type: 'sunfish', hab: 'pelagic', depth: [0, 1112], typ: [0, 400], size: 1.8, sizeTxt: 'Up to ~3.3 m tall', iucn: 'VU', regions: ['ID', 'AU'], ab: 0.004, c: ['#a8b0b8', '#d8dde2'], fact: 'Sunfish are the heaviest bony fish. They dive into cold deep water to eat jellyfish, then bask near the surface to warm up. Many sunfish seen off Bali are actually the closely related bump-head sunfish (Mola alexandrini).' },
    { id: 'pyrosome', name: 'Pyrosome', sci: 'Pyrosoma atlanticum', type: 'pyrosome', hab: 'pelagic', depth: [0, 800], typ: [200, 700], size: 0.4, iucn: 'NE', regions: 'all', ab: 0.12, kind: 'Tunicate colony', c: ['#e8b8c8', '#f5d8e0'], glow: { c: '#a8ffe0', s: 'body' }, fact: 'Not one animal but a tube-shaped colony of thousands of tiny clones. Its name means "fire body" — the whole colony glows when touched.' },
    { id: 'lanternfish', name: 'Lanternfish', sci: 'Myctophidae (family)', type: 'fish', hab: 'pelagic', depth: [0, 1000], typ: [250, 1000], size: 0.08, iucn: 'LC', regions: 'all', ab: 0.9, school: [5, 12], c: ['#3a4a5a', '#c0cad4', '#88ffff'], f: { h: 0.3, eyeBig: 1 }, glow: { c: '#7ff6ff', s: 'belly' }, fact: 'Possibly the most abundant vertebrates on Earth. Every night they rise hundreds of metres to feed near the surface — part of the biggest daily migration on the planet — and sink back before dawn.' },
    { id: 'hatchetfish', name: 'Silver hatchetfish', sci: 'Argyropelecus aculeatus', type: 'fish', hab: 'pelagic', depth: [100, 600], typ: [300, 600], size: 0.07, iucn: 'LC', regions: 'all', ab: 0.6, school: [3, 8], c: ['#c8d4de', '#ffffff', '#7fd0ff'], f: { h: 0.95, eyeBig: 1 }, glow: { c: '#7fd0ff', s: 'belly' }, fact: 'Thin as a blade and mirror-silver. Light organs on its belly match the faint light from above, erasing its silhouette — a trick called counter-illumination.' },
    { id: 'viperfish', pred: 1, name: 'Sloane\'s viperfish', sci: 'Chauliodus sloani', type: 'fish', hab: 'pelagic', depth: [200, 4700], typ: [250, 1500], size: 0.3, iucn: 'LC', regions: 'all', ab: 0.15, c: ['#2a3140', '#45506a', '#99ffff'], f: { h: 0.15, teeth: 2, eyeBig: 1 }, glow: { c: '#8ff', s: 'belly' }, fact: 'Its fangs are so long they don\'t fit inside its closed mouth. A light organ on its long first fin ray may work as a lure.' },
    { id: 'giant_squid', name: 'Giant squid', sci: 'Architeuthis dux', type: 'squid', hab: 'pelagic', depth: [300, 1000], size: 12, sizeTxt: 'Up to ~12–13 m incl. tentacles', iucn: 'LC', regions: 'all', ab: 0.008, kind: 'Cephalopod', c: ['#b8503a', '#e8a08a'], fact: 'Shares the record for the largest eyes in the animal kingdom — about the size of a dinner plate. It was first photographed alive in 2004 and first filmed in its deep-sea home in 2012.' },
    { id: 'vampire_squid', name: 'Vampire squid', sci: 'Vampyroteuthis infernalis', type: 'squid', hab: 'pelagic', depth: [600, 3000], typ: [600, 1200], size: 0.3, iucn: 'LC', regions: 'all', ab: 0.06, kind: 'Cephalopod', c: ['#4a1a2a', '#7a2a3a'], f: { vampire: 1 }, glow: { c: '#5fd4ff', s: 'tips' }, fact: 'Neither vampire nor squid, it drifts in low-oxygen water eating "marine snow". When threatened it releases a cloud of glowing blue mucus instead of ink.' },
    { id: 'glass_octopus', name: 'Glass octopus', sci: 'Vitreledonella richardi', type: 'octopus', hab: 'pelagic', depth: [200, 1000], size: 0.45, iucn: 'NE', regions: 'all', ab: 0.03, c: ['#d8f0f8', '#f0a060'], f: { glass: 1 }, fact: 'Almost completely see-through — only its eyes, optic nerves and gut are visible. Its eyes are long and narrow, which may shrink its shadow when seen from below.' },
    { id: 'frilled', pred: 1, name: 'Frilled shark', sci: 'Chlamydoselachus anguineus', type: 'eel', hab: 'pelagic', depth: [50, 1500], typ: [500, 1000], size: 1.7, sizeTxt: 'Up to ~2 m', iucn: 'LC', regions: ['AU'], ab: 0.02, kind: 'Shark', c: ['#6a5040', '#8a6a58', '#f5f0e0'], f: { frilled: 1 }, fact: 'An eel-like shark with about 300 needle-sharp, three-pointed teeth. Its pregnancy may last up to 3.5 years — possibly the longest of any animal with a backbone.' },
    { id: 'blobfish', name: 'Blobfish', sci: 'Psychrolutes marcidus', type: 'fish', hab: 'benthic', lift: 0.25, depth: [600, 1200], size: 0.3, iucn: 'NE', regions: ['AU'], ab: 0.06, c: ['#e8b8b0', '#f4d6cf', '#c98a80'], f: { h: 0.55, rattail: 1, blob: 1 }, fact: 'In its high-pressure home it looks like a fairly normal fish. The famous saggy "blob" face only appears when it is hauled to the surface and its jelly-like body sags.' },

    // ---------- Midnight zone ----------
    { id: 'anglerfish', pred: 1, name: 'Humpback anglerfish', sci: 'Melanocetus johnsonii', type: 'fish', hab: 'pelagic', depth: [100, 4500], typ: [200, 2000], size: 0.18, iucn: 'LC', regions: 'all', ab: 0.06, c: ['#26221f', '#3a332e', '#99ffff'], f: { h: 0.85, teeth: 1, lure: 1, tail: 'round' }, glow: { c: '#9ff5ff', s: 'lure' }, fact: 'Only females have the glowing lure, lit by bacteria living inside it. Males are tiny, have no lure, and spend their short lives sniffing out a female.' },
    { id: 'fangtooth', pred: 1, name: 'Common fangtooth', sci: 'Anoplogaster cornuta', type: 'fish', hab: 'pelagic', depth: [500, 5000], typ: [500, 2000], size: 0.16, iucn: 'LC', regions: 'all', ab: 0.08, c: ['#3a2a28', '#553a36', '#ffffff'], f: { h: 0.62, teeth: 2, tail: 'round' }, fact: 'Relative to body size it has the biggest teeth of any fish. Its two longest lower fangs slide into pockets beside its brain when it shuts its mouth.' },
    { id: 'dragonfish', pred: 1, name: 'Stoplight loosejaw', sci: 'Malacosteus niger', type: 'fish', hab: 'pelagic', depth: [500, 4000], typ: [500, 1500], size: 0.25, iucn: 'LC', regions: 'all', ab: 0.08, c: ['#141414', '#2a2a2a', '#ff3333'], f: { h: 0.14, teeth: 1 }, glow: { c: '#ff3a3a', s: 'red' }, fact: 'One of very few animals that makes red light, which most deep-sea animals can\'t see — so it can spotlight prey without being noticed. Its lower jaw has no floor.' },
    { id: 'black_swallower', pred: 1, name: 'Black swallower', sci: 'Chiasmodon niger', type: 'fish', hab: 'pelagic', depth: [700, 2745], size: 0.25, iucn: 'LC', regions: 'all', ab: 0.05, c: ['#1c1c20', '#2e2e36', '#ffffff'], f: { h: 0.35, teeth: 1, belly: 1 }, fact: 'Can swallow fish twice its length and ten times its weight by stretching its stomach. Some have been found dead, burst by prey that rotted before it could be digested.' },
    { id: 'gulper', name: 'Pelican (gulper) eel', sci: 'Eurypharynx pelecanoides', type: 'eel', hab: 'pelagic', depth: [500, 3000], typ: [1000, 2500], size: 0.75, iucn: 'LC', regions: 'all', ab: 0.04, c: ['#141418', '#2a2a30', '#ff66aa'], f: { gulper: 1 }, glow: { c: '#ff7ab8', s: 'tail' }, fact: 'Its huge, loose jaw opens like a pelican\'s pouch. The tip of its whip-like tail has a light organ that may lure prey.' },
    { id: 'atolla', name: 'Atolla jellyfish', sci: 'Atolla wyvillei', type: 'jelly', hab: 'pelagic', depth: [500, 4000], typ: [600, 2000], size: 0.15, iucn: 'NE', regions: 'all', ab: 0.12, c: ['#a01a2a', '#d0404a'], f: { atolla: 1 }, glow: { c: '#3aa8ff', s: 'ring' }, fact: 'The "alarm jellyfish": when attacked it flashes a spinning ring of blue light — a burglar alarm that may attract bigger predators to eat its attacker.' },
    { id: 'siphonophore', name: 'Giant siphonophore', sci: 'Praya dubia', type: 'siphonophore', hab: 'pelagic', depth: [700, 1000], size: 40, sizeTxt: 'Up to ~40–50 m long', iucn: 'NE', regions: 'all', ab: 0.02, c: ['#d8e8f8', '#f0f8ff'], glow: { c: '#9fd6ff', s: 'beads' }, fact: 'A colony of specialised clones strung together, rivalling the blue whale as one of the longest animals on Earth.' },
    { id: 'comb_jelly', name: 'Comb jelly', sci: 'Ctenophora (phylum)', type: 'jelly', hab: 'pelagic', depth: [0, 7000], typ: [200, 7000], size: 0.1, iucn: 'NE', regions: 'all', ab: 0.1, kind: 'Comb jelly', c: ['#e0f0ff', '#ffffff'], f: { comb: 1 }, glow: { c: '#b0e0ff', s: 'body' }, fact: 'Rows of beating hair-like "combs" scatter light into shimmering rainbows. Comb jellies live from the surface to over 7,000 m deep.' },
    { id: 'bamboo_coral', name: 'Bamboo coral', sci: 'Isididae (family)', type: 'bamboo', hab: 'benthic', depth: [300, 4800], typ: [800, 3000], size: 1.3, iucn: 'NE', regions: 'all', ab: 0.1, kind: 'Deep-sea coral', c: ['#f0ece0', '#6a4a3a'], fact: 'Its skeleton alternates chalky and horny joints like bamboo. Growth rings in the skeleton record centuries of ocean history.' },
    { id: 'sea_lily', name: 'Stalked crinoid (sea lily)', sci: 'Isocrinida (order)', type: 'crinoid', hab: 'benthic', depth: [100, 6000], typ: [200, 2000], size: 0.6, iucn: 'NE', regions: 'all', ab: 0.1, kind: 'Echinoderm', c: ['#e8d8a8', '#f5e8c0'], fact: 'A relative of starfish that looks like a plant. Some stalked crinoids can let go of the seabed and crawl away from predators.' },
    { id: 'isopod', name: 'Supergiant isopod', sci: 'Bathynomus raksasa', type: 'crust', hab: 'benthic', lift: 0.12, depth: [950, 1260], size: 0.33, iucn: 'NE', regions: ['ID'], ab: 0.3, kind: 'Crustacean', c: ['#b8a8b8', '#8a7a8a'], f: { iso: 1 }, fact: 'Described in 2020 from the deep sea off southern Java — "raksasa" means giant in Indonesian. Giant isopods can go for years without eating.' },
    { id: 'tripod', name: 'Tripod fish', sci: 'Bathypterois grallator', type: 'fish', hab: 'benthic', lift: 0.5, depth: [875, 4720], typ: [1000, 4000], size: 0.35, iucn: 'LC', regions: 'all', ab: 0.08, c: ['#c8c0b0', '#e6e0d4', '#6a6358'], f: { h: 0.2, tripod: 1 }, fact: 'Stands on three stilt-like fin rays, facing into the current, waiting for tiny prey to drift into its forward-pointing fins. Its eyes are tiny; it hunts mostly by touch.' },
    { id: 'grenadier', name: 'Abyssal grenadier (rattail)', sci: 'Coryphaenoides armatus', type: 'fish', hab: 'pelagic', depth: [282, 5180], typ: [2000, 4700], size: 0.9, iucn: 'LC', regions: 'all', ab: 0.08, c: ['#8a8f98', '#c8ccd4', '#4a4e56'], f: { h: 0.3, rattail: 1, eyeBig: 1 }, fact: 'One of the most widespread deep-sea fish. Grenadiers are often first to arrive at a dead whale or a baited camera, tracking food by smell.' },
    { id: 'dumbo', name: 'Dumbo octopus', sci: 'Grimpoteuthis sp.', type: 'octopus', hab: 'pelagic', depth: [1000, 6957], typ: [1500, 5000], size: 0.3, iucn: 'NE', regions: 'all', ab: 0.05, c: ['#f0a8a0', '#f8d0c8'], f: { dumbo: 1 }, fact: 'It "flies" using the ear-like fins on its head. In 2020 one was filmed at 6,957 m in the Java Trench off Indonesia — the deepest octopus ever recorded.' },
    { id: 'sea_pig', name: 'Sea pig', sci: 'Scotoplanes globosa', type: 'cuke', hab: 'benthic', lift: 0.3, depth: [1000, 6000], typ: [1200, 5000], size: 0.15, iucn: 'NE', regions: 'all', ab: 0.15, kind: 'Sea cucumber', c: ['#f0b8c0', '#f8d8dc'], f: { pig: 1 }, fact: 'A sea cucumber that walks on tube-feet "legs". Herds graze the deep-sea mud, often facing into the current to smell food falling from above.' },
    { id: 'headless_chicken', name: 'Swimming sea cucumber', sci: 'Enypniastes eximia', type: 'cuke', hab: 'pelagic', depth: [500, 6000], typ: [2500, 5000], size: 0.25, iucn: 'NE', regions: 'all', ab: 0.05, kind: 'Sea cucumber', c: ['#d84a5a', '#f0808a'], glow: { c: '#8ff0ff', s: 'body' }, fact: 'Nicknamed the "headless chicken monster". It swims with a veil-like fin, glows when disturbed, and can shed its glowing skin onto attackers.' },

    // ---------- Abyss & hadal trenches ----------
    { id: 'sea_pen', name: 'Deep-sea sea pen', sci: 'Umbellula sp.', type: 'seapen', hab: 'benthic', depth: [200, 6100], typ: [1000, 5500], size: 1.4, iucn: 'NE', regions: 'all', ab: 0.1, kind: 'Soft coral (sea pen)', c: ['#e8e0c8', '#f0a8b8'], fact: 'A colony of polyps on one long stalk anchored in mud. It holds its feathery crown into the current to catch drifting food.' },
    { id: 'alicella', name: 'Supergiant amphipod', sci: 'Alicella gigantea', type: 'crust', hab: 'pelagic', depth: [4850, 7000], size: 0.28, sizeTxt: 'Up to ~34 cm', iucn: 'NE', regions: 'all', ab: 0.08, kind: 'Crustacean', c: ['#f0e0d0', '#e0c0b0'], fact: 'About ten times bigger than a typical amphipod — a textbook case of "abyssal gigantism", where some deep-sea animals grow unusually large.' },
    { id: 'xeno', name: 'Xenophyophore', sci: 'Xenophyophorea', type: 'xeno', hab: 'benthic', lift: 0.3, depth: [1000, 10641], typ: [4000, 10641], size: 0.12, sizeTxt: 'Up to ~20 cm', iucn: 'NE', regions: 'all', ab: 0.25, kind: 'Single-celled organism', c: ['#b0a08a', '#8a7a64'], fact: 'A single cell up to 20 cm across — among the largest cells on Earth. They build fragile shells from sediment and have been found as deep as 10,641 m.' },
    { id: 'snailfish', name: 'Hadal snailfish', sci: 'Liparidae (Pseudoliparis & kin)', type: 'fish', hab: 'pelagic', depth: [6000, 8336], typ: [6500, 8200], size: 0.25, iucn: 'NE', regions: 'all', ab: 0.25, c: ['#f2d9d9', '#fff2f2', '#e5b5b5'], f: { h: 0.4, rattail: 1 }, fact: 'The deepest fish ever filmed was a snailfish at 8,336 m in the Izu-Ogasawara Trench. Its soft, jelly-like body and flexible bones help it cope with crushing pressure.' },
    { id: 'hirondellea', name: 'Hadal amphipod', sci: 'Hirondellea gigas', type: 'crust', hab: 'pelagic', depth: [6000, 10935], typ: [7000, 10935], size: 0.05, iucn: 'NE', regions: 'all', ab: 0.5, school: [3, 8], kind: 'Crustacean', c: ['#f5ece0', '#e8d8c8'], fact: 'Lives at the very bottom of the Challenger Deep. It can digest sunken wood with a special enzyme and coats itself in an aluminium gel that may help protect it.' },
    // ---------- More Maldivian species ----------
    { id: 'yellowfin', name: 'Yellowfin tuna', sci: 'Thunnus albacares', type: 'fish', hab: 'pelagic', pred: 1, depth: [0, 250], typ: [0, 100], size: 1.5, sizeTxt: 'Up to ~2.4 m', iucn: 'LC', regions: ['MV'], range: 'Tropical and subtropical oceans worldwide', ab: 0.04, school: [6, 12], c: ['#2a3a6a', '#e8ecf0', '#f5d020'], f: { h: 0.28, tail: 'lunate', finc: '#f5d020' }, fact: 'The backbone of the Maldives\' traditional pole-and-line fishery. Tuna must keep swimming to breathe, and their fins fold into grooves to cut drag.' },
    { id: 'sailfish', name: 'Indo-Pacific sailfish', sci: 'Istiophorus platypterus', type: 'fish', hab: 'pelagic', pred: 1, depth: [0, 200], typ: [0, 50], size: 2.5, sizeTxt: 'Up to ~3.4 m', iucn: 'LC', regions: ['MV'], range: 'Tropical and subtropical Indian, Pacific and Atlantic oceans', ab: 0.008, c: ['#20305a', '#e8ecf2', '#3a70d0'], f: { h: 0.2, bill: 1, tail: 'lunate', dorsal: 'sail', finc: '#3a70d0' }, fact: 'Raises its huge sail-like dorsal fin to herd sardines, then slashes through the school with its bill. Often called the fastest fish, though its real top speed is debated.' },
    { id: 'blue_marlin', name: 'Blue marlin', sci: 'Makaira nigricans', type: 'fish', hab: 'pelagic', pred: 1, depth: [0, 300], typ: [0, 100], size: 3.5, sizeTxt: 'Females up to ~5 m', iucn: 'VU', regions: ['MV'], range: 'Tropical and warm oceans worldwide', ab: 0.005, c: ['#1a2a58', '#eef0f6', '#4a7ad8'], f: { h: 0.24, bill: 1, tail: 'lunate', dorsal: 'tall' }, fact: 'Females grow far larger than males — the biggest can top 800 kg. Like sailfish, it stuns prey with sweeps of its bill.' },
    { id: 'mahi', name: 'Mahi-mahi (dolphinfish)', sci: 'Coryphaena hippurus', type: 'fish', hab: 'pelagic', pred: 1, depth: [0, 85], typ: [0, 30], size: 1, sizeTxt: 'Up to ~2 m', iucn: 'LC', regions: ['MV'], range: 'Warm oceans worldwide', ab: 0.02, school: [2, 5], c: ['#2a9a6a', '#f5e04a', '#3a80d8'], f: { h: 0.3, hump: 1, dorsal: 'long' }, fact: 'Shimmers gold, green and blue when alive, but the colours fade quickly after death. It grows very fast and rarely lives more than about 5 years.' },
    { id: 'silver_sprat', bait: 1, name: 'Silver sprat', sci: 'Spratelloides gracilis', type: 'fish', hab: 'pelagic', depth: [0, 30], typ: [0, 15], size: 0.08, sizeTxt: 'Up to ~10 cm', iucn: 'LC', regions: ['MV'], range: 'Tropical Indo-West Pacific', ab: 0.08, school: [60, 110], c: ['#8ab8c8', '#eef6f8', '#3a6a80'], f: { h: 0.2 }, fact: 'A tiny silvery fish that gathers in huge shoals over reefs. Maldivian pole-and-line tuna fishers catch it as live bait — and when predators attack, the shoal packs into a swirling "bait ball".' },
    { id: 'bigeye_trevally', name: 'Bigeye trevally', sci: 'Caranx sexfasciatus', type: 'fish', hab: 'reef', pred: 1, depth: [1, 100], typ: [5, 50], size: 0.7, sizeTxt: 'Up to ~1.2 m', iucn: 'LC', regions: ['MV'], range: 'Tropical Indo-Pacific and eastern Pacific', ab: 0.05, school: [30, 55], c: ['#7a8a98', '#e0e6ea', '#2a3440'], f: { h: 0.4, eyeBig: 1 }, fact: 'Forms huge, slowly spinning schools during the day and scatters to hunt at night.' },
    { id: 'indian_mackerel', bait: 1, name: 'Indian mackerel', sci: 'Rastrelliger kanagurta', type: 'fish', hab: 'pelagic', depth: [20, 90], size: 0.3, iucn: 'DD', regions: ['MV'], range: 'Indian Ocean and western Pacific', ab: 0.08, school: [30, 50], c: ['#5a7a8a', '#e0e8ec', '#2a3a44'], f: { h: 0.25, pattern: 'dots' }, fact: 'Swims with its mouth wide open to filter plankton through comb-like gill rakers, in fast-moving schools.' },
    { id: 'batfish', name: 'Longfin batfish', sci: 'Platax teira', type: 'fish', hab: 'reef', mood: 'curious', depth: [0, 20], size: 0.5, sizeTxt: 'Up to ~60 cm', iucn: 'LC', regions: ['MV'], range: 'Tropical Indo-West Pacific', ab: 0.06, school: [2, 6], c: ['#b8b8b0', '#2a2a2a', '#f0d040'], f: { h: 1.0, dorsal: 'bat', pattern: 'vbands' }, fact: 'Famously curious, batfish often swim right up to divers. Juveniles have extremely tall fins and drift like dead leaves to fool predators.' },
    { id: 'porcupinefish', name: 'Porcupinefish', sci: 'Diodon hystrix', type: 'fish', hab: 'reef', mood: 'puff', depth: [0, 50], size: 0.5, sizeTxt: 'Up to ~90 cm', iucn: 'LC', regions: ['MV'], range: 'Tropical seas worldwide', ab: 0.04, c: ['#9a8a6a', '#f0ead8', '#3a3024'], f: { h: 0.5, w: 0.95, tail: 'round', pattern: 'dots', spines: 1, eyeBig: 1 }, fact: 'Covered in spines that stand straight out when it inflates. It hunts snails and crabs at night and crushes them with fused, beak-like teeth.' },
    { id: 'boxfish', name: 'Yellow boxfish', sci: 'Ostracion cubicus', type: 'fish', hab: 'reef', depth: [1, 45], size: 0.3, sizeTxt: 'Up to ~45 cm', iucn: 'NE', regions: ['MV'], range: 'Tropical Indo-Pacific and Red Sea', ab: 0.04, c: ['#f5d21b', '#fff6c0', '#111111'], f: { h: 0.45, w: 1, box: 1, tail: 'round', pattern: 'dots' }, fact: 'Its body is a rigid box of fused bony plates. Juveniles are bright yellow with black spots — a warning that it can release a toxin from its skin when stressed.' },
    { id: 'garden_eel', name: 'Spotted garden eel', sci: 'Heteroconger hassi', type: 'eel', hab: 'benthic', mood: 'hide', depth: [7, 45], typ: [10, 30], size: 0.35, sizeTxt: 'Up to ~40 cm', iucn: 'LC', regions: ['MV'], range: 'Tropical Indo-Pacific and Red Sea', ab: 0.06, school: [10, 20], c: ['#f0ead8', '#1a1a1a', '#e8d898'], f: { garden: 1 }, fact: 'Lives in colonies of hundreds, each eel anchored tail-first in its own sand burrow, picking plankton from the current. When a diver gets close, they all sink back into their holes.' },
    { id: 'blue_shark', name: 'Blue shark', sci: 'Prionace glauca', type: 'shark', hab: 'pelagic', pred: 1, depth: [0, 1160], typ: [0, 350], size: 2.5, sizeTxt: 'Up to ~3.8 m', iucn: 'NT', regions: ['MV'], range: 'Open ocean worldwide, from the tropics to cool temperate seas', ab: 0.008, c: ['#2f5fa8', '#f0f4fa'], f: { h: 0.08, longFins: 1 }, fact: 'A slender, deep-blue ocean wanderer that makes enormous migrations, including across entire oceans. It is the most heavily fished shark species in the world.' },
    { id: 'mako', name: 'Shortfin mako', sci: 'Isurus oxyrinchus', type: 'shark', hab: 'pelagic', pred: 1, depth: [0, 888], typ: [0, 150], size: 3, sizeTxt: 'Up to ~4 m', iucn: 'EN', regions: ['MV'], range: 'Tropical and temperate oceans worldwide', ab: 0.005, c: ['#3a5a8a', '#f0f2f6'], f: { h: 0.11 }, fact: 'The fastest shark, with bursts estimated at around 70 km/h, and it can leap several metres out of the water. Like the great white, it keeps its muscles warm.' },
    { id: 'bottlenose', name: 'Bottlenose dolphin', sci: 'Tursiops truncatus', type: 'whale', hab: 'pelagic', pred: 1, mood: 'curious', depth: [0, 300], typ: [0, 50], size: 2.8, sizeTxt: 'Up to ~4 m', iucn: 'LC', regions: ['MV'], range: 'Warm and temperate seas worldwide', ab: 0.012, school: [2, 6], c: ['#7a8490', '#e0e4e8'], f: { dolphin: 1 }, fact: 'Each dolphin develops its own "signature whistle" that works like a name — other dolphins use it to call that individual.' },

    // ---------- Visitors from other oceans (not native to the Maldives) ----------
    { id: 'great_white', name: 'Great white shark', sci: 'Carcharodon carcharias', type: 'shark', hab: 'pelagic', pred: 1, depth: [0, 1200], typ: [0, 250], size: 4.5, sizeTxt: 'Usually 3.5–5 m; up to ~6 m', iucn: 'VU', regions: 'world', range: 'South Africa, Australia, California, Mexico and other temperate coasts', ab: 0.005, c: ['#5f6a72', '#f0f0ee'], f: { h: 0.14 }, fact: 'The largest predatory fish. Off South Africa it ambushes seals from below so fast it can launch itself completely out of the water. Unlike most sharks, it keeps its body warmer than the sea around it.' },
    { id: 'bull_shark', name: 'Bull shark', sci: 'Carcharhinus leucas', type: 'shark', hab: 'pelagic', pred: 1, depth: [0, 152], typ: [0, 30], size: 2.4, sizeTxt: 'Up to ~3.4 m', iucn: 'VU', regions: 'world', range: 'Warm coasts worldwide — and far up rivers such as the Amazon and Zambezi', ab: 0.008, c: ['#8a8a7e', '#eeeee6'], f: { h: 0.13 }, fact: 'One of the few sharks that can live in fresh water. Bull sharks have been found thousands of kilometres up the Amazon River and in Lake Nicaragua.' },
    { id: 'lemon_shark', name: 'Lemon shark', sci: 'Negaprion brevirostris', type: 'shark', hab: 'reef', pred: 1, depth: [0, 92], typ: [0, 30], size: 2.8, sizeTxt: 'Up to ~3.4 m', iucn: 'VU', regions: 'world', range: 'Western Atlantic and eastern Pacific coasts — Bahamas, Florida, Brazil, Mexico', ab: 0.01, c: ['#b8a878', '#f0ead8'], f: { h: 0.12 }, fact: 'Named for its yellowish skin. Females return to the mangrove nursery where they were born to give birth — scientists have tracked this for decades in Bimini, Bahamas.' },
    { id: 'greenland_shark', name: 'Greenland shark', sci: 'Somniosus microcephalus', type: 'shark', hab: 'pelagic', depth: [0, 2200], typ: [200, 1200], size: 4.5, sizeTxt: 'Up to ~6.4 m', iucn: 'VU', regions: 'world', range: 'Cold Arctic and North Atlantic waters', ab: 0.006, c: ['#5a5650', '#7a746c'], f: { h: 0.13, nurse: 1 }, fact: 'Estimated to live around 400 years — the longest-lived animal with a backbone known. It cruises at under 3 km/h and grows only about 1 cm a year.' },
    { id: 'orca', name: 'Orca (killer whale)', sci: 'Orcinus orca', type: 'whale', hab: 'pelagic', pred: 1, depth: [0, 760], typ: [0, 100], size: 7, sizeTxt: 'Up to ~9 m (males)', iucn: 'DD', regions: 'world', range: 'All oceans, most common in cold waters; occasionally seen around the Maldives', ab: 0.003, school: [3, 6], c: ['#101216', '#f4f4f4'], f: { orca: 1 }, fact: 'The largest dolphin. Different orca families specialise in different prey — fish, seals, even great white sharks — and pass their hunting techniques down the generations.' },
    { id: 'sea_lion', name: 'California sea lion', sci: 'Zalophus californianus', type: 'whale', hab: 'pelagic', pred: 1, mood: 'curious', depth: [0, 274], typ: [0, 40], size: 2.2, sizeTxt: 'Males up to ~2.4 m', iucn: 'LC', regions: 'world', range: 'Pacific coast of North America, from Canada to Mexico', ab: 0.01, c: ['#6a5040', '#8a6a50'], f: { sealion: 1 }, fact: 'It "flies" underwater with its big front flippers, and young sea lions are famously playful, often darting right up to divers.' },
    { id: 'bluefin', name: 'Atlantic bluefin tuna', sci: 'Thunnus thynnus', type: 'fish', hab: 'pelagic', pred: 1, depth: [0, 985], typ: [0, 500], size: 2.5, sizeTxt: 'Up to ~3 m and 680 kg', iucn: 'LC', regions: 'world', range: 'Atlantic Ocean and Mediterranean Sea', ab: 0.015, school: [3, 8], c: ['#1f2f55', '#dfe4ea', '#b0b8c0'], f: { h: 0.28, tail: 'lunate' }, fact: 'A warm-bodied giant that crosses entire oceans. It keeps its muscles far warmer than the water, letting it hunt in cold seas.' },
    { id: 'guineafowl_puffer', name: 'Guineafowl puffer', sci: 'Arothron meleagris', type: 'fish', hab: 'reef', mood: 'puff', depth: [1, 73], size: 0.35, sizeTxt: 'Up to ~50 cm', iucn: 'LC', regions: 'world', range: 'Tropical Pacific, from East Africa to the Americas', ab: 0.03, c: ['#1a1a1a', '#ffffff'], f: { h: 0.55, w: 0.95, tail: 'round', pattern: 'whitespots' }, fact: 'When threatened it gulps water and swells into a ball too big to swallow. Its organs contain tetrodotoxin, one of the deadliest natural poisons.' },
    { id: 'mandarinfish', name: 'Mandarinfish', sci: 'Synchiropus splendidus', type: 'fish', hab: 'reef', depth: [1, 18], size: 0.06, iucn: 'LC', regions: 'world', range: 'Western Pacific: Philippines, Indonesia, Palau and northern Australia', ab: 0.04, c: ['#1f6ad8', '#f58a1a', '#2ad0a0'], f: { h: 0.35, w: 0.7, tail: 'round', pattern: 'swirl' }, fact: 'One of very few animals with a true blue pigment made in its own cells. At dusk, pairs rise off the reef together to spawn.' },
    { id: 'yellow_tang', name: 'Yellow tang', sci: 'Zebrasoma flavescens', type: 'fish', hab: 'reef', depth: [2, 46], size: 0.2, iucn: 'LC', regions: 'world', range: 'Hawaii and nearby central Pacific islands', ab: 0.15, school: [2, 8], c: ['#f5d80a', '#f8e878', '#ffffff'], f: { h: 0.72, tail: 'lunate' }, fact: 'One of Hawaii\'s best-known reef fish. At night its bright yellow fades and a pale stripe appears, helping it hide while it sleeps.' },
    { id: 'stoplight_parrot', name: 'Stoplight parrotfish', sci: 'Sparisoma viride', type: 'fish', hab: 'reef', depth: [1, 50], size: 0.5, sizeTxt: 'Up to ~64 cm', iucn: 'LC', regions: 'world', range: 'Caribbean and western Atlantic', ab: 0.06, c: ['#2aa088', '#f5d040', '#e84a8a'], f: { h: 0.38, tail: 'lunate', pattern: 'hlines' }, fact: 'At night many parrotfish sleep inside a bubble of mucus they produce, which may hide their scent from predators such as moray eels.' },
    { id: 'queen_angel', name: 'Queen angelfish', sci: 'Holacanthus ciliaris', type: 'fish', hab: 'reef', depth: [1, 70], size: 0.35, sizeTxt: 'Up to ~45 cm', iucn: 'LC', regions: 'world', range: 'Caribbean and western Atlantic', ab: 0.06, c: ['#2a7ad8', '#f5d21b', '#1a3a8a'], f: { h: 0.7, tail: 'round', tailc: '#f5d21b', finc: '#f5d21b' }, fact: 'Named for the blue-ringed "crown" spot on its forehead. Adults feed mainly on sponges.' },
    { id: 'goliath', name: 'Atlantic goliath grouper', sci: 'Epinephelus itajara', type: 'fish', hab: 'reef', pred: 1, mood: 'curious', depth: [0, 100], typ: [0, 50], size: 2, sizeTxt: 'Up to ~2.5 m and 360 kg', iucn: 'VU', regions: 'world', range: 'Western Atlantic, Caribbean and West Africa', ab: 0.01, c: ['#6a6a4a', '#b8b088', '#3a3a2a'], f: { h: 0.42, tail: 'round', pattern: 'blotch' }, fact: 'Can weigh more than 360 kg and makes loud booming sounds with its swim bladder to warn off intruders — including divers.' },
    { id: 'sardine', bait: 1, name: 'Sardine (pilchard)', sci: 'Sardinops sagax', type: 'fish', hab: 'pelagic', depth: [0, 200], typ: [0, 50], size: 0.2, iucn: 'LC', regions: 'world', range: 'Temperate Pacific and Indian Oceans — South Africa, Australia, California, Japan', ab: 0.05, school: [60, 110], c: ['#3a6a8a', '#e8eef2', '#2a3a4a'], f: { h: 0.2, pattern: 'dots' }, fact: 'Each winter billions of sardines travel up South Africa\'s east coast in the "Sardine Run", chased by dolphins, sharks, gannets and whales.' },
    { id: 'green_moray', name: 'Green moray', sci: 'Gymnothorax funebris', type: 'eel', hab: 'benthic', lift: 0.03, depth: [0, 50], size: 1.8, sizeTxt: 'Up to ~2.5 m', iucn: 'LC', regions: 'world', range: 'Western Atlantic and Caribbean', ab: 0.03, c: ['#5a7a2a', '#7a9a3a', '#2a3a10'], f: { moray: 1 }, fact: 'Its skin is actually brownish-blue; a yellow coat of protective mucus makes it look green.' },
    { id: 'big_belly_seahorse', name: 'Big-belly seahorse', sci: 'Hippocampus abdominalis', type: 'seahorse', hab: 'benthic', depth: [0, 104], size: 0.3, sizeTxt: 'Up to ~35 cm', iucn: 'LC', regions: 'world', range: 'Southern Australia and New Zealand', ab: 0.04, c: ['#e0a040', '#f0d090', '#8a5a20'], fact: 'One of the largest seahorses. As in all seahorses, the male carries the eggs in a belly pouch and gives birth.' },
    { id: 'leafy_seadragon', name: 'Leafy seadragon', sci: 'Phycodurus eques', type: 'seahorse', hab: 'reef', depth: [4, 50], size: 0.3, sizeTxt: 'Up to ~35 cm', iucn: 'LC', regions: 'world', range: 'Southern Australia only', ab: 0.03, c: ['#c89a40', '#8aa048', '#e0c070'], f: { leafy: 1 }, fact: 'Leaf-shaped skin flaps make it look like drifting seaweed. It steers with nearly invisible fins, and males carry the eggs on the underside of their tail.' },
    { id: 'giant_pacific_octopus', name: 'Giant Pacific octopus', sci: 'Enteroctopus dofleini', type: 'octopus', hab: 'reef', depth: [0, 1500], typ: [0, 200], size: 4, sizeTxt: 'Arm span usually 3–5 m', iucn: 'NE', regions: 'world', range: 'North Pacific: Alaska, Canada, Japan, Korea', ab: 0.01, c: ['#b85a3a', '#e08a6a'], fact: 'The largest octopus. It can recognise individual people, open jars, and each of its 2,000-plus suckers can taste what it touches.' },
    { id: 'blue_ringed', name: 'Greater blue-ringed octopus', sci: 'Hapalochlaena lunulata', type: 'octopus', hab: 'reef', depth: [0, 20], size: 0.12, sizeTxt: 'About 10–12 cm across', iucn: 'NE', regions: 'world', range: 'Western Pacific and northern Australia', ab: 0.02, c: ['#d8b870', '#2a7aff'], f: { rings: 1 }, fact: 'Tiny, yet its bite carries tetrodotoxin strong enough to kill an adult. Its blue rings flash brightly as a warning when it is disturbed.' },
    { id: 'box_jelly', name: 'Australian box jellyfish', sci: 'Chironex fleckeri', type: 'jelly', hab: 'pelagic', depth: [0, 20], size: 0.3, sizeTxt: 'Bell ~30 cm; tentacles ~3 m', iucn: 'NE', regions: 'world', range: 'Northern Australia and the western Indo-Pacific', ab: 0.02, c: ['#d8e8f0', '#f0f8ff'], f: { box: 1 }, fact: 'Among the most venomous animals on Earth. Unlike most jellyfish it has 24 eyes and swims actively rather than just drifting.' },
    { id: 'lions_mane', name: 'Lion\'s mane jellyfish', sci: 'Cyanea capillata', type: 'jelly', hab: 'pelagic', depth: [0, 40], typ: [0, 20], size: 1, sizeTxt: 'Bell up to ~2 m; tentacles 30 m+', iucn: 'NE', regions: 'world', range: 'Cold northern seas: Arctic, North Atlantic and North Pacific', ab: 0.01, c: ['#c85a2a', '#f0a060'], f: { mane: 1 }, fact: 'The largest known jellyfish: a bell up to about 2 m across, with tentacles that can stretch over 30 m.' },
    { id: 'moon_jelly', name: 'Moon jellyfish', sci: 'Aurelia aurita', type: 'jelly', hab: 'pelagic', depth: [0, 200], typ: [0, 30], size: 0.3, iucn: 'NE', regions: 'world', range: 'Coastal waters almost everywhere on Earth', ab: 0.04, school: [3, 8], c: ['#e8eef8', '#f0c8e0'], f: { moon: 1 }, fact: 'The four horseshoe-shaped rings visible through its bell are its reproductive organs. It is one of the most widespread jellyfish in the world.' },
    { id: 'man_o_war', name: 'Portuguese man o\' war', sci: 'Physalia physalis', type: 'jelly', hab: 'pelagic', depth: [0, 2], size: 0.3, sizeTxt: 'Float ~30 cm; tentacles 10 m+', iucn: 'NE', regions: 'world', range: 'Warm open oceans, blown along by the wind', ab: 0.03, kind: 'Siphonophore', c: ['#8a6ad8', '#4a8ad8'], f: { mow: 1 }, fact: 'Not a jellyfish but a colony of specialised animals. Its gas-filled float works as a sail, and its stinging tentacles can trail 10 m or more below.' },
    { id: 'humboldt_squid', name: 'Humboldt squid', sci: 'Dosidicus gigas', type: 'squid', hab: 'pelagic', pred: 1, depth: [0, 1200], typ: [200, 700], size: 1.5, sizeTxt: 'Mantle up to ~1.5 m', iucn: 'LC', regions: 'world', range: 'Eastern Pacific, from California to Chile', ab: 0.02, school: [5, 10], kind: 'Cephalopod', c: ['#c83a3a', '#f09090'], fact: 'Hunts in packs of hundreds, flashing red and white — which earned it the nickname "red devil". It rises from the deep at night to feed.' },
    { id: 'firefly_squid', name: 'Firefly squid', sci: 'Watasenia scintillans', type: 'squid', hab: 'pelagic', depth: [0, 600], typ: [200, 400], size: 0.07, iucn: 'NE', regions: 'world', range: 'Western Pacific around Japan', ab: 0.1, school: [6, 12], kind: 'Cephalopod', c: ['#6a4a8a', '#9a7ab8'], glow: { c: '#3a8aff', s: 'body' }, fact: 'Covered in light organs. Each spring huge numbers rise to the surface in Toyama Bay, Japan, lighting the water electric blue.' },
    { id: 'oarfish', name: 'Giant oarfish', sci: 'Regalecus glesne', type: 'eel', hab: 'pelagic', depth: [0, 1000], typ: [200, 1000], size: 8, sizeTxt: 'Usually 3–8 m', iucn: 'LC', regions: 'world', range: 'Deep water in tropical and temperate oceans worldwide', ab: 0.004, kind: 'Bony fish', c: ['#c8d0d8', '#e8eef4', '#e83a4a'], f: { oar: 1 }, fact: 'The longest bony fish. It often hangs vertically in the water, and rare sightings at the surface probably inspired many sea-serpent legends.' },
    { id: 'opah', name: 'Opah (moonfish)', sci: 'Lampris guttatus', type: 'fish', hab: 'pelagic', depth: [50, 500], size: 1.2, sizeTxt: 'Up to ~2 m', iucn: 'LC', regions: 'world', range: 'Temperate and tropical oceans worldwide', ab: 0.01, c: ['#c84a5a', '#f0a0a8', '#e82a2a'], f: { h: 0.6, tail: 'lunate', pattern: 'whitespots', finc: '#e82a2a' }, fact: 'The first fish found to be fully warm-blooded: it circulates heated blood through its whole body, keeping its heart and brain warm in the cold deep.' },
    { id: 'african_coelacanth', name: 'West Indian Ocean coelacanth', sci: 'Latimeria chalumnae', type: 'fish', hab: 'reef', depth: [100, 400], typ: [150, 250], size: 1.8, sizeTxt: 'Up to ~2 m', iucn: 'CR', regions: 'world', range: 'Western Indian Ocean: Comoros, South Africa, Tanzania', ab: 0.004, c: ['#2a3d6a', '#e8eef8', '#1a2a50'], f: { h: 0.3, lobed: 1, pattern: 'whitespots', tail: 'round' }, fact: 'Found alive in 1938 off South Africa, long after coelacanths were thought extinct. It can live around 100 years and gives birth to live young after a pregnancy of about 5 years.' },
    { id: 'barreleye', name: 'Barreleye', sci: 'Macropinna microstoma', type: 'fish', hab: 'pelagic', depth: [600, 800], size: 0.15, iucn: 'NE', regions: 'world', range: 'North Pacific: California to Japan', ab: 0.05, c: ['#2a2a30', '#4a4a55', '#40e060'], f: { h: 0.3, dome: 1 }, fact: 'Its head has a transparent, fluid-filled dome, and its tubular green eyes can rotate to look straight up through it for the silhouettes of prey.' },
    { id: 'ratfish', name: 'Spotted ratfish (ghost shark)', sci: 'Hydrolagus colliei', type: 'fish', hab: 'pelagic', depth: [0, 971], typ: [50, 400], size: 0.9, sizeTxt: 'Up to ~1 m', iucn: 'LC', regions: 'world', range: 'Northeast Pacific: Alaska to Mexico', ab: 0.03, kind: 'Chimaera (ghost shark)', c: ['#8a7a6a', '#d8d0c8', '#f0f0f0'], f: { h: 0.3, rattail: 1, eyeBig: 1, pattern: 'whitespots' }, fact: 'A relative of sharks whose lineage split off around 400 million years ago. Its big green eyes reflect light like a cat\'s.' },
    { id: 'bigfin_squid', name: 'Bigfin squid', sci: 'Magnapinna sp.', type: 'squid', hab: 'pelagic', depth: [1900, 6200], typ: [2000, 6000], size: 7, sizeTxt: 'Up to ~8 m, mostly thin arms', iucn: 'NE', regions: 'world', range: 'Deep water in the Atlantic, Pacific and Indian oceans', ab: 0.01, kind: 'Cephalopod', c: ['#e8c8c0', '#f0e0d8'], f: { bigfin: 1 }, fact: 'Filmed only a handful of times, it hangs in the dark with huge fins and thin arms bent at sharp "elbows", trailing several metres below.' },
    { id: 'deep_lizardfish', name: 'Highfin lizardfish', sci: 'Bathysaurus mollis', type: 'fish', hab: 'benthic', lift: 0.15, pred: 1, depth: [1000, 4900], typ: [1500, 4500], size: 0.6, iucn: 'LC', regions: 'world', range: 'Deep seafloors of all oceans', ab: 0.05, c: ['#8a8a80', '#b8b8b0', '#ffffff'], f: { h: 0.18, teeth: 1 }, fact: 'One of the deepest-living predatory fish on the seafloor. It is a hermaphrodite, making both eggs and sperm — useful where mates are rare.' },
    // ---------- More reef builders & reef life ----------
    { id: 'porites', name: 'Massive lobe coral', sci: 'Porites lobata', type: 'massive', hab: 'benthic', depth: [0, 30], typ: [1, 20], size: 1.5, sizeTxt: 'Colonies usually 1–3 m; some over 5 m', iucn: 'NT', regions: 'all', ab: 0.35, kind: 'Hard coral', c: ['#c8b080', '#9a8458'], tints: ['#ffffff', '#e8f0c8', '#f0d8c0', '#d8d0f0'], fact: 'Grows only about 1 cm a year, yet colonies can be several metres across and centuries old. Growth bands in its skeleton record past sea temperatures, like tree rings.' },
    { id: 'scroll_coral', name: 'Scroll coral', sci: 'Turbinaria reniformis', type: 'scroll', hab: 'benthic', depth: [2, 30], size: 0.8, iucn: 'VU', regions: 'all', ab: 0.3, kind: 'Hard coral', c: ['#d8c448', '#a89428'], tints: ['#ffffff', '#f0f0d0', '#d0e8c0'], fact: 'Grows as yellow, scroll-shaped plates that can build big colonies on reef slopes. It copes with murky water better than many corals.' },
    { id: 'bubble_coral', name: 'Bubble coral', sci: 'Plerogyra sinuosa', type: 'bubble', hab: 'benthic', depth: [1, 50], typ: [3, 30], size: 0.5, iucn: 'NT', regions: 'all', ab: 0.2, kind: 'Hard coral', c: ['#ece6d0', '#d0dcc0'], tints: ['#ffffff', '#e0f0ff', '#f0e8ff'], fact: 'By day it inflates grape-like bubbles packed with algae to soak up sunlight; at night the bubbles shrink and stinging tentacles come out to feed.' },
    { id: 'leather_coral', name: 'Leather coral', sci: 'Sarcophyton sp.', type: 'leather', hab: 'benthic', depth: [1, 30], size: 0.6, iucn: 'NE', regions: 'all', ab: 0.3, kind: 'Soft coral', c: ['#d8cca0', '#f0ead0'], tints: ['#ffffff', '#e0f0d0', '#f0d8c8'], fact: 'A soft coral with a leathery, mushroom-shaped cap covered in tiny polyps. It defends itself with toxic chemicals, some of which are being studied as possible medicines.' },
    { id: 'cup_coral', name: 'Orange cup coral', sci: 'Tubastraea coccinea', type: 'cups', hab: 'benthic', depth: [1, 110], typ: [3, 40], size: 0.25, iucn: 'LC', regions: 'all', ab: 0.35, kind: 'Hard coral (no algae)', c: ['#f07418', '#ffb048'], fact: 'Unlike reef-building corals it has no algae, so it grows in shade under overhangs and in caves. At night its bright orange polyps open to catch plankton.' },
    { id: 'sea_whip', name: 'Sea whip', sci: 'Junceella sp.', type: 'whip', hab: 'benthic', depth: [5, 60], typ: [10, 40], size: 1.4, iucn: 'NE', regions: 'all', ab: 0.25, kind: 'Soft coral (gorgonian)', c: ['#e85a2a', '#f4f0e0'], tints: ['#ffffff', '#ffe0a0', '#ffc0c0'], fact: 'Long, unbranched gorgonians that bend with the current. Tiny whip gobies and shrimp often spend their whole lives on a single whip.' },
    { id: 'finger_coral', name: 'Finger coral', sci: 'Acropora humilis', type: 'digitate', hab: 'benthic', depth: [0, 20], typ: [0, 10], size: 0.5, iucn: 'NT', regions: 'all', ab: 0.5, kind: 'Hard coral', c: ['#a8a878', '#d8ecf8'], tints: ['#ffffff', '#d0e0ff', '#ffe0d0', '#e0d0ff'], fact: 'Grows short, thick finger-like branches on shallow reef crests, where the waves hit hardest.' },
    { id: 'seagrass', name: 'Seagrass', sci: 'Thalassia hemprichii', type: 'grass', hab: 'benthic', depth: [0, 12], size: 0.3, iucn: 'LC', regions: 'all', ab: 0.6, kind: 'Seagrass (flowering plant)', c: ['#4a8a38', '#7ab050'], fact: 'Not a seaweed but a flowering plant that lives underwater. Seagrass meadows feed turtles and dugongs and lock away large amounts of carbon.' },
    { id: 'halimeda', name: 'Cactus alga', sci: 'Halimeda opuntia', type: 'algae', hab: 'benthic', depth: [0, 50], size: 0.2, iucn: 'NE', regions: 'all', ab: 0.5, kind: 'Green alga', c: ['#7ab058', '#a8d080'], fact: 'Its segments are stiffened with calcium carbonate. When they die they crumble into white sand — much of the sand on atoll beaches comes from Halimeda.' },
    { id: 'tube_sponge', name: 'Tube sponge', sci: 'Callyspongia sp.', type: 'tubes', hab: 'benthic', depth: [3, 50], size: 0.5, iucn: 'NE', regions: 'all', ab: 0.3, kind: 'Sponge', c: ['#e8e0f0', '#8a5aa8'], tints: ['#c070e0', '#6090f0', '#f0c040', '#f08080'], fact: 'Sponges are among the oldest animals on Earth. A tube sponge draws water in through tiny pores in its walls and pumps it out of the open top.' },
    { id: 'xmas_worm', name: 'Christmas tree worm', sci: 'Spirobranchus giganteus', type: 'xmas', hab: 'benthic', mood: 'hide', depth: [0, 30], size: 0.06, sizeTxt: 'Plumes about 4 cm tall', iucn: 'NE', regions: 'all', ab: 0.4, school: [3, 8], kind: 'Segmented worm', c: ['#f4f4f4', '#d0d0d0'], tints: ['#ff4040', '#ffd040', '#40a0ff', '#ffffff', '#ff8020', '#b060ff'], fact: 'A worm living in a tube inside living coral. Its two spiral plumes catch plankton — and if you swim too close, it snaps back into its tube in a split second.' },
  ],
};

if (typeof module !== 'undefined') module.exports = REEF_DATA;
